begin;
    with j as (select * from jsonb_to_recordset($law7v005$[{"code_id":"APK_RF","article_number":"98","version_date":"2002-07-24","article_text":"1. Ответчик и другие лица, чьи права и (или) законные интересы нарушены обеспечением иска, после вступления в законную силу судебного акта арбитражного суда об отказе в удовлетворении иска вправе требовать от лица, по заявлению которого были приняты обеспечительные меры, возмещения убытков в порядке и в размере, которые предусмотрены гражданским законодательством, или выплаты компенсации.\n\n2. Размер компенсации определяется судом в зависимости от характера нарушения и иных обстоятельств дела с учетом требований разумности и справедливости по спорам, указанным в статье 2251 настоящего Кодекса, в пределах от десяти тысяч до одного миллиона рублей, по другим спорам - от одной тысячи до одного миллиона рублей.\n\n3. Иск о возмещении убытков или выплате компенсации предъявляется в арбитражный суд, рассматривавший дело, по которому принимались обеспечительные меры.\n\n4. Правила, установленные настоящей статьей, применяются в случаях оставления иска без рассмотрения по основаниям, предусмотренным пунктами 1 и 2 части 1 статьи 148 настоящего Кодекса, а также в случаях прекращения производства по делу по основаниям, предусмотренным пунктами 2 - 4 части 1 статьи 150 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 98. Убытки и компенсации в связи с обеспечением иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9071162f82f65013de2cb77792a4b8c7d45bdf36fc372f8c0c0e72b346005cf"},{"code_id":"APK_RF","article_number":"99","version_date":"2002-07-24","article_text":"1. Арбитражный суд по заявлению организации или гражданина вправе принять предварительные обеспечительные меры, направленные на обеспечение имущественных интересов заявителя до предъявления иска.\n\nЗаявление об обеспечении имущественных интересов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n11. Арбитражный суд вправе по заявлению Банка России, поданному в случае установления им отрицательного значения величины собственных средств (капитала) кредитной организации, страховой организации, негосударственного пенсионного фонда, принять предварительные обеспечительные меры, предусматривающие наложение ареста на денежные средства, ценные бумаги и недвижимое имущество лиц, контролирующих кредитную организацию, страховую организацию, негосударственный пенсионный фонд, до подачи заявления о привлечении указанных лиц к субсидиарной ответственности, ответственности в форме возмещения убытков в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\". Арбитражный суд выносит определение об оставлении заявления Банка России о принятии предварительных обеспечительных мер без движения, если при рассмотрении вопроса о принятии данного заявления к производству установит, что оно не содержит сведений, позволяющих с минимально необходимой степенью достоверности сделать обоснованные предположения о том, что ответчик, указанный в заявлении, является или являлся контролирующим лицом. Рассмотрение судом дела об оспаривании включения лица в перечень контролирующих кредитную организацию лиц в соответствии со статьей 576 Федерального закона от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\", перечень контролирующих страховую организацию лиц или перечень контролирующих негосударственный пенсионный фонд лиц в соответствии со статьей 767-1 Федерального закона от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\" не препятствует принятию арбитражным судом заявления Банка России о принятии предварительных обеспечительных мер, рассмотрению данного заявления и принятию предварительных обеспечительных мер в соответствии с настоящей частью.\n\nРазмер предварительных обеспечительных мер, принимаемых арбитражным судом по заявлению Банка России в соответствии с настоящей частью, не может превышать величину денежных средств, необходимых для восполнения собственных средств (капитала) кредитной организации, страховой организации, негосударственного пенсионного фонда в целях приведения их к величине, необходимой и достаточной для выполнения указанными организациями требований федеральных законов и нормативных актов Банка России.\n\n(Дополнение частью - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\n2. Предварительные обеспечительные меры принимаются арбитражным судом по правилам, предусмотренным настоящей главой, с особенностями, установленными настоящей статьей.\n\nВ случае непредставления указанного документа арбитражный суд вправе предложить заявителю предоставить встречное обеспечение в соответствии со статьей 94 настоящего Кодекса и оставляет заявление об обеспечении имущественных интересов без движения по правилам статьи 128 настоящего Кодекса до представления документа, подтверждающего произведенное встречное обеспечение.\n\nПри подаче Банком России заявления о принятии предварительных обеспечительных мер в соответствии с частью 11 настоящей статьи предоставления встречного обеспечения в соответствии со статьей 94 настоящего Кодекса не требуется. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\nВ случае, если по требованию, в связи с которым подано заявление об обеспечении имущественных интересов, в силу закона обязательно соблюдение претензионного или иного досудебного порядка урегулирования спора, в определении устанавливаются срок для направления претензии (требования) другой стороне, не превышающий пятнадцати дней со дня вынесения определения, и срок для подачи искового заявления по такому требованию, не превышающий пяти дней со дня истечения установленного законом или договором срока для принятия сторонами мер по досудебному урегулированию в соответствии с частью 5 статьи 4 настоящего Кодекса. Если указанный порядок не является обязательным, в определении устанавливается срок, не превышающий пятнадцати дней со дня вынесения определения, для подачи искового заявления по требованию, в связи с которым судом приняты меры по обеспечению имущественных интересов заявителя.\n\nПри подаче Банком России заявления о принятии предварительных обеспечительных мер в соответствии с частью 11 настоящей статьи в определении об обеспечении имущественных интересов устанавливается срок, не превышающий тридцати дней со дня вынесения определения, для подачи искового заявления по требованию, в связи с которым судом приняты меры по обеспечению имущественных интересов Банка России. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\n(Часть в редакции Федерального закона от 01.07.2017 № 147-ФЗ)\n\nОб отмене обеспечения имущественных интересов выносится определение.\n\nКопии определения направляются заявителю и иным заинтересованным лицам не позднее следующего дня после дня вынесения определения.\n\nЛицо, в отношении имущества которого были приняты предварительные обеспечительные меры в соответствии с частью 11 настоящей статьи, вправе требовать по своему выбору от Банка России возмещения убытков или выплаты компенсации в порядке, предусмотренном статьей 98 настоящего Кодекса, если Банком России в установленный судом срок не было подано исковое заявление по требованию, в связи с которым арбитражным судом были приняты меры по обеспечению имущественных интересов Банка России, или если вступившим в законную силу судебным актом арбитражного суда в иске было отказано. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)","article_title":"Статья 99. Предварительные обеспечительные меры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31e045cf3384e7aa6090b6a5d438d3384d694e1d5178707655984ded1b0a11f2"},{"code_id":"BK_RF","article_number":"1","version_date":"1998-07-31","article_text":"1. К бюджетным правоотношениям относятся:\n\nотношения,  возникающие между субъектами бюджетных правоотношений в процессе формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации,  осуществления государственных (муниципальных)  заимствований,  регулирования государственного (муниципального)  долга; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ,  от 02.08.2019 № 278-ФЗ)\n\nотношения,  возникающие между субъектами бюджетных правоотношений в процессе составления и рассмотрения проектов бюджетов бюджетной системы Российской Федерации,  утверждения и исполнения бюджетов бюджетной системы Российской Федерации,  контроля за их исполнением,  осуществления бюджетного учета,  составления,  рассмотрения и утверждения бюджетной отчетности. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Настоящий Кодекс устанавливает правовой статус участников бюджетного процесса,  правовые основы казначейского сопровождения,  применения бюджетных мер принуждения за совершение бюджетных нарушений. (В редакции федеральных законов от 26.07.2019 № 199-ФЗ,  от 01.07.2021 № 244-ФЗ)","article_title":"Статья 1. Правоотношения,  регулируемые Бюджетным кодексом Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33dc8ff9a180d26000babe6e25ef00221db4bfd1d86d1334b82a1d671b1f7beb"},{"code_id":"BK_RF","article_number":"10","version_date":"1998-07-31","article_text":"К бюджетам бюджетной системы Российской Федерации относятся:\n\nфедеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации;\n\nбюджеты субъектов Российской Федерации и бюджеты территориальных государственных внебюджетных фондов;\n\nместные бюджеты,  в том числе:\n\nбюджеты муниципальных районов,  бюджеты муниципальных округов,  бюджеты городских округов,  бюджеты городских округов с внутригородским делением,  бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nбюджеты городских и сельских поселений,  бюджеты внутригородских районов. (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 10. Структура бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50494720d2362ba6d723ff09eb7145444152da6beb325f7d64175f0262c9e23f"},{"code_id":"BK_RF","article_number":"11","version_date":"1998-07-31","article_text":"Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации разрабатываются и утверждаются в форме федеральных законов,  бюджеты субъектов Российской Федерации и бюджеты территориальных государственных внебюджетных фондов разрабатываются и утверждаются в форме законов субъектов Российской Федерации,  местные бюджеты разрабатываются и утверждаются в форме муниципальных правовых актов представительных органов муниципальных образований.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 11. Правовая форма бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"568a143c4a92f91048daaeec89ce8dade0b130ac7d6e6492a015397159a11df1"},{"code_id":"BK_RF","article_number":"12","version_date":"1998-07-31","article_text":"Финансовый год соответствует календарному году и длится с 1 января по 31 декабря.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 12. Финансовый год","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c789ef65f4a656d5e053804f16c3fab7d953f77736b84d55fb83e0ca9c3b4c9"},{"code_id":"BK_RF","article_number":"13","version_date":"1998-07-31","article_text":"Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации предназначены для исполнения расходных обязательств Российской Федерации.\n\nИспользование федеральными органами государственной власти иных форм образования и расходования денежных средств,  предназначенных для исполнения расходных обязательств Российской Федерации,  не допускается.\n\nФедеральный бюджет и свод консолидированных бюджетов субъектов Российской Федерации (без учета межбюджетных трансфертов между этими бюджетами)  образуют консолидированный бюджет Российской Федерации.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 13. Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d22c29391587f6764649cb0c09669f4c440cfdfbce8ff5ced15e6d72eae1ed51"},{"code_id":"BK_RF","article_number":"14","version_date":"1998-07-31","article_text":"Каждый субъект Российской Федерации имеет собственный бюджет и бюджет территориального государственного внебюджетного фонда.\n\nБюджет субъекта Российской Федерации (региональный бюджет)  и бюджет территориального государственного внебюджетного фонда предназначены для исполнения расходных обязательств субъекта Российской Федерации.\n\nИспользование органами государственной власти субъектов Российской Федерации иных форм образования и расходования денежных средств для исполнения расходных обязательств субъектов Российской Федерации не допускается.\n\nВ бюджетах субъектов Российской Федерации в соответствии с бюджетной классификацией Российской Федерации раздельно предусматриваются средства,  направляемые на исполнение расходных обязательств субъектов Российской Федерации,  возникающих в связи с осуществлением органами государственной власти субъектов Российской Федерации полномочий по предметам ведения субъектов Российской Федерации и полномочий по предметам совместного ведения,  указанных в частях 1 и 5 статьи 44 Федерального закона от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\",  и расходных обязательств субъектов Российской Федерации,  осуществляемых за счет субвенций из федерального бюджета. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nБюджет субъекта Российской Федерации и свод бюджетов муниципальных образований,  входящих в состав субъекта Российской Федерации (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет субъекта Российской Федерации.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 14. Бюджет субъекта Российской Федерации и бюджет территориального государственного внебюджетного фонда","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d503066f4ae75d90dfc811e75e37301d9bf35b64fdc03c0a78d1bc1f8d042ef3"},{"code_id":"BK_RF","article_number":"15","version_date":"1998-07-31","article_text":"Каждое муниципальное образование имеет собственный бюджет.\n\nБюджет муниципального образования (местный бюджет)  предназначен для исполнения расходных обязательств муниципального образования.\n\nИспользование органами местного самоуправления иных форм образования и расходования денежных средств для исполнения расходных обязательств муниципальных образований не допускается.\n\nВ местных бюджетах в соответствии с бюджетной классификацией Российской Федерации раздельно предусматриваются средства,  направляемые на исполнение расходных обязательств муниципальных образований,  возникающих в связи с осуществлением органами местного самоуправления полномочий по вопросам местного значения,  и расходных обязательств муниципальных образований,  исполняемых за счет субвенций из других бюджетов бюджетной системы Российской Федерации для осуществления отдельных государственных полномочий.\n\nБюджет муниципального района (районный бюджет)  и свод бюджетов городских и сельских поселений,  входящих в состав муниципального района (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет муниципального района.\n\nВ качестве составной части бюджетов городских,  сельских поселений,  внутригородских районов,  муниципальных районов (в отношении населенных пунктов,  других территорий,  расположенных на межселенных территориях) ,  муниципальных округов,  городских округов,  внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя могут быть предусмотрены сметы доходов и расходов отдельных населенных пунктов,  других территорий,  не являющихся муниципальными образованиями. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\nБюджет городского округа с внутригородским делением и свод бюджетов внутригородских районов,  входящих в состав городского округа с внутригородским делением (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет городского округа с внутригородским делением. (Дополнение частью - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 15. Местный бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"67929442ae2ee61570e1e77f58603a00e1a2fd979125ba703e4fc46550b5dded"},{"code_id":"BK_RF","article_number":"16","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 16.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"17","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 17.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"18","version_date":"1998-07-31","article_text":"1. Бюджетная классификация Российской Федерации является группировкой доходов,  расходов и источников финансирования дефицитов бюджетов бюджетной системы Российской Федерации,  используемой для составления и исполнения бюджетов,  а также группировкой доходов,  расходов и источников финансирования дефицитов бюджетов и (или)  операций сектора государственного управления,  используемой для ведения бюджетного (бухгалтерского)  учета,  составления бюджетной (бухгалтерской)  и иной финансовой отчетности,  обеспечивающей сопоставимость показателей бюджетов бюджетной системы Российской Федерации. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n2. Определение принципов назначения,  структуры,  порядка формирования и применения кодов бюджетной классификации Российской Федерации,  а также присвоение кодов составным частям бюджетной классификации Российской Федерации,  которые в соответствии с настоящим Кодексом являются едиными для бюджетов бюджетной системы Российской Федерации,  осуществляются Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 настоящей статьи. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n3. Утверждение или изменение нормативных правовых актов Министерства финансов Российской Федерации,  регулирующих вопросы,  указанные в пункте 2 настоящей статьи,  пункте 6,  абзацах третьем и четвертом пункта 9 статьи 20,  абзацах четвертом - шестом пункта 4,  пунктах 7 и 8 статьи 21,  абзацах втором и третьем пункта 5 статьи 23,  пунктах 3 - 5 статьи 231 настоящего Кодекса,  осуществляется исключительно в связи с составлением или принятием федеральных законов о федеральном бюджете или о внесении изменений в федеральный закон о федеральном бюджете,  но не более одного раза в связи с составлением и не более одного раза в связи с принятием такого федерального закона,  за исключением случаев,  установленных в абзаце втором пункта 6,  абзаце пятом пункта 9 статьи 20,  пункте 9 статьи 21 и абзаце четвертом пункта 5 статьи 23 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\n4. Нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в пункте 2 настоящей статьи,  пункте 6 и абзаце третьем пункта 9 статьи 20,  пунктах 7 и 8 статьи 21,  абзаце втором пункта 5 статьи 23,  пунктах 3 - 5 статьи 231 настоящего Кодекса,  включая изменения в них,  обратной силы не имеют и применяются к отношениям,  возникшим не ранее дня их вступления в силу,  за исключением случаев,  установленных пунктом 9 статьи 21 и абзацем четвертым пункта 5 статьи 23 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 18. Бюджетная классификация Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcf1cb086a0855625535868452798b9d13d91c3560c1d6951ebf9d66aa267306"},{"code_id":"BK_RF","article_number":"19","version_date":"1998-07-31","article_text":"Бюджетная классификация Российской Федерации включает:\n\nклассификацию доходов бюджетов;\n\nклассификацию расходов бюджетов;\n\nклассификацию источников финансирования дефицитов бюджетов;\n\nклассификацию операций публично-правовых образований (далее - классификация операций сектора государственного управления) .\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 19. Состав бюджетной классификации Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4cda38fdcdf6a4291ae9def7d33e8761e6a45941d159ec3385e1b5bbb22a3419"},{"code_id":"BK_RF","article_number":"2","version_date":"1998-07-31","article_text":"Бюджетное законодательство Российской Федерации состоит из настоящего Кодекса и принятых в соответствии с ним федеральных законов о федеральном бюджете,  федеральных законов о бюджетах государственных внебюджетных фондов Российской Федерации,  законов субъектов Российской Федерации о бюджетах субъектов Российской Федерации,  законов субъектов Российской Федерации о бюджетах территориальных государственных внебюджетных фондов,  муниципальных правовых актов представительных органов муниципальных образований о местных бюджетах (далее - закон (решение)  о бюджете) ,  иных федеральных законов,  законов субъектов Российской Федерации и муниципальных правовых актов представительных органов муниципальных образований,  регулирующих правоотношения,  указанные в статье 1 настоящего Кодекса.\n\nФедеральные законы,  законы субъектов Российской Федерации,  муниципальные правовые акты представительных органов муниципальных образований,  предусмотренные частью первой настоящей статьи,  не могут противоречить настоящему Кодексу.\n\nВнесение изменений в Бюджетный кодекс Российской Федерации,  а также приостановление,  отмена и признание утратившими силу положений Бюджетного кодекса Российской Федерации осуществляются отдельными федеральными законами и не могут быть включены в тексты федеральных законов,  изменяющих (приостанавливающих,  отменяющих,  признающих утратившими силу)  другие законодательные акты Российской Федерации или содержащих самостоятельный предмет правового регулирования. (Дополнение частью - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 2. Структура бюджетного законодательства Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff9b76412fffd26b6534c1f5793eaa3c346ba8928eee1694573d7e7fed056498"},{"code_id":"BK_RF","article_number":"20","version_date":"1998-07-31","article_text":"1. Код классификации доходов бюджетов Российской Федерации состоит из:\n\n1)  кода главного администратора доходов бюджета;\n\n2)  кода вида доходов;\n\n3)  кода подвида доходов;\n\n4)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. (Пункт утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n3. Код вида доходов включает группу,  подгруппу,  статью,  подстатью и элемент дохода.\n\n4. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами доходов бюджетов являются:\n\n1)  налоговые и неналоговые доходы:\n\nналоги на прибыль,  доходы;\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nналоги на товары (работы,  услуги) ,  реализуемые на территории Российской Федерации;\n\nналоги на товары,  ввозимые на территорию Российской Федерации;\n\nналоги на совокупный доход;\n\nналоги на имущество;\n\nналоги,  сборы и регулярные платежи за пользование природными ресурсами;\n\nгосударственная пошлина;\n\nзадолженность и перерасчеты по отмененным налогам,  сборам и иным обязательным платежам;\n\nстраховые взносы на обязательное социальное страхование; (Дополнение абзацем - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nдоходы от внешнеэкономической деятельности;\n\nдоходы от использования имущества,  находящегося в государственной и муниципальной собственности;\n\nплатежи при пользовании природными ресурсами;\n\nдоходы от оказания платных услуг и компенсации затрат государства;\n\nдоходы от продажи материальных и нематериальных активов;\n\nадминистративные платежи и сборы;\n\nштрафы,  санкции,  возмещение ущерба;\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпоступления (перечисления)  по урегулированию расчетов между бюджетами бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\nпрочие неналоговые доходы;\n\n2)  безвозмездные поступления:\n\nбезвозмездные поступления от нерезидентов;\n\nбезвозмездные поступления от других бюджетов бюджетной системы Российской Федерации;\n\nбезвозмездные поступления от государственных (муниципальных)  организаций;\n\nбезвозмездные поступления от негосударственных организаций;\n\nбезвозмездные поступления от наднациональных организаций;\n\nпоступления (перечисления)  для осуществления возврата (зачета)  излишне уплаченных или излишне взысканных сумм налогов,  сборов и иных платежей,  а также сумм процентов за несвоевременное осуществление такого возврата и процентов,  начисленных на излишне взысканные суммы; (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\nдоходы бюджетов бюджетной системы Российской Федерации от возврата остатков субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  прошлых лет; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nвозврат остатков субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  прошлых лет; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпрочие безвозмездные поступления.\n\n5. Доходы,  указанные в абзацах втором,  четвертом - десятом подпункта 1 пункта 4 настоящей статьи,  являются налоговыми доходами бюджетов. Доходы,  указанные в абзацах одиннадцатом - двадцать втором подпункта 1 пункта 4 настоящей статьи,  являются неналоговыми доходами бюджетов. (В редакции федеральных законов от 24.07.2009 № 213-ФЗ; от 07.05.2013 № 104-ФЗ)\n\n6. Единый для бюджетов бюджетной системы Российской Федерации перечень статей и подстатей доходов бюджетов утверждается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце первом настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых либо изменение действующих источников доходов федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов и местных бюджетов. (Дополнение абзацем - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n7. Код элемента доходов устанавливается в зависимости от полномочия по установлению и нормативному правовому регулированию налогов,  сборов и иных обязательных платежей,  других доходов бюджетов бюджетной системы Российской Федерации,  а также в зависимости от наличия прав требования к плательщикам по неналоговым доходам и безвозмездным поступлениям и соответствует бюджету бюджетной системы Российской Федерации.\n\n8. Едиными для бюджетов бюджетной системы Российской Федерации элементами доходов являются:\n\n1)  федеральный бюджет;\n\n2)  бюджеты субъектов Российской Федерации;\n\n3)  бюджеты муниципальных районов;\n\n31)  бюджеты муниципальных округов; (Дополнение подпунктом - Федеральный закон от 01.10.2020 № 311-ФЗ)\n\n4)  бюджеты городских округов;\n\n41)  бюджеты городских округов с внутригородским делением; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n5)  бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n6)  бюджеты городских поселений; (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n61)  бюджеты сельских поселений; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n62)  бюджеты внутригородских районов; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n7)  бюджет Фонда пенсионного и социального страхования Российской Федерации; (В редакции  Федерального закона от 14.07.2022 № 264-ФЗ)\n\n8)  (Подпункт утратил силу  - Федеральный закон от 14.07.2022 № 264-ФЗ)\n\n9)  бюджет Федерального фонда обязательного медицинского страхования;\n\n10)  бюджеты территориальных фондов обязательного медицинского страхования.\n\n9. Для детализации поступлений по кодам классификации доходов применяется код подвида доходов.\n\nМинистерство финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса утверждает: (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nобщие требования к порядку формирования перечня кодов подвидов доходов бюджетов бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\nперечень кодов подвидов по видам доходов,  главными администраторами которых являются органы государственной власти (государственные органы)  Российской Федерации,  Центральный банк Российской Федерации,  органы управления государственными внебюджетными фондами Российской Федерации и (или)  находящиеся в их ведении казенные учреждения,  иные организации,  наделенные полномочиями главного администратора доходов федерального бюджета. (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце четвертом настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых либо изменение действующих источников доходов федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов и местных бюджетов в связи с принятием федеральных законов,  регулирующих вопросы установления нормативов распределения доходов между бюджетами бюджетной системы Российской Федерации. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nФинансовый орган субъекта Российской Федерации утверждает перечень кодов подвидов по видам доходов,  главными администраторами которых являются органы государственной власти субъектов Российской Федерации,  органы управления территориальными государственными внебюджетными фондами и (или)  находящиеся в их ведении казенные учреждения. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nФинансовый орган муниципального образования утверждает перечень кодов подвидов по видам доходов,  главными администраторами которых являются органы местного самоуправления и (или)  находящиеся в их ведении казенные учреждения. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 20. Классификация доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22efb538f3c7ed69dea9c6468ddd5c8ba9323356e5efd7bee4586610d88b521a"},{"code_id":"BK_RF","article_number":"21","version_date":"1998-07-31","article_text":"1. Код классификации расходов бюджетов состоит из:\n\n1)  кода главного распорядителя бюджетных средств;\n\n2)  кода раздела,  подраздела,  целевой статьи и вида расходов;\n\n3)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. Перечень главных распорядителей средств федерального бюджета,  бюджета субъекта Российской Федерации,  бюджетов государственных внебюджетных фондов,  местного бюджета устанавливается законом (решением)  о соответствующем бюджете в составе ведомственной структуры расходов.\n\n3. Едиными для бюджетов бюджетной системы Российской Федерации разделами и подразделами классификации расходов бюджетов являются:\n\n1)  общегосударственные вопросы:\n\nфункционирование Президента Российской Федерации;\n\nфункционирование высшего должностного лица субъекта Российской Федерации и муниципального образования;\n\nфункционирование законодательных (представительных)  органов государственной власти и представительных органов муниципальных образований;\n\nфункционирование  Правительства  Российской Федерации,  высших исполнительных органов субъектов Российской Федерации,  местных администраций; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nсудебная система;\n\nобеспечение деятельности финансовых,  налоговых и таможенных органов и органов финансового (финансово-бюджетного)  надзора;\n\nобеспечение проведения выборов и референдумов;\n\nмеждународные отношения и международное сотрудничество;\n\nгосударственный материальный резерв;\n\nфундаментальные исследования;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nрезервные фонды;\n\nприкладные научные исследования в области общегосударственных вопросов;\n\nдругие общегосударственные вопросы;\n\n2)  национальная оборона:\n\nВооруженные Силы Российской Федерации;\n\nредакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 21. Классификация расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48dbe8c06e6d873f6ca0122b25c054532b4c3a8254d92cc03d2dd6fd5d766384"},{"code_id":"BK_RF","article_number":"22","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 22.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"23","version_date":"1998-07-31","article_text":"1. Код классификации источников финансирования дефицитов бюджетов состоит из:\n\n1)  кода главного администратора источников финансирования дефицитов бюджетов;\n\n2)  кода группы,  подгруппы,  статьи и вида источника финансирования дефицитов бюджетов;\n\n3)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. (Пункт утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n3. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами источников финансирования дефицитов бюджетов являются:\n\n1)  источники внутреннего финансирования дефицитов бюджетов:\n\nгосударственные (муниципальные)  ценные бумаги,  номинальная стоимость которых указана в валюте Российской Федерации;\n\nкредиты кредитных организаций в валюте Российской Федерации;\n\nбюджетные кредиты из других бюджетов бюджетной системы Российской Федерации; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nкредиты международных финансовых организаций в валюте Российской Федерации;\n\nкредиты иностранных банков в валюте Российской Федерации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nизменение остатков средств на счетах по учету средств бюджета;\n\nиные источники внутреннего финансирования дефицитов бюджетов;\n\n2)  источники внешнего финансирования дефицитов бюджетов:\n\nгосударственные ценные бумаги,  номинальная стоимость которых указана в иностранной валюте;\n\nкредиты иностранных государств,  включая целевые иностранные кредиты,  международных финансовых организаций,  иных субъектов международного права,  иностранных юридических лиц в иностранной валюте; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nкредиты кредитных организаций в иностранной валюте;\n\nбюджетные кредиты в иностранной валюте,  предоставленные Российской Федерацией в рамках использования целевых иностранных кредитов; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nиные источники внешнего финансирования дефицитов бюджетов.\n\n4. Перечень статей источников финансирования дефицитов бюджетов утверждается законом (решением)  о соответствующем бюджете при утверждении источников финансирования дефицита бюджета. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n5. Министерство финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса утверждает: (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\nобщие требования к порядку формирования перечня кодов статей и видов источников финансирования дефицитов бюджетов;\n\nперечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы государственной власти Российской Федерации,  органы управления государственными внебюджетными фондами Российской Федерации и (или)  находящиеся в их ведении казенные учреждения.\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце третьем настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых источников финансирования дефицит\n\nприкладные научные исследования в области общегосударственных вопросов;\n\nдругие общегосударственные вопросы;\n\n2)  национальная оборона:\n\nВооруженные Силы Российской Федерации;\n\nмодернизация Вооруженных Сил Российской Федерации и воинских формирований;\n\nмобилизационная и вневойсковая подготовка;\n\nмобилизационная подготовка экономики;\n\nподготовка и участие в обеспечении коллективной безопасности и миротворческой деятельности;\n\nядерно-оружейный комплекс;\n\nреализация международных обязательств в сфере военно-технического сотрудничества;\n\nприкладные научные исследования в области национальной обороны;\n\nдругие вопросы в области национальной обороны;\n\n3)  национальная безопасность и правоохранительная деятельность:\n\nорганы прокуратуры и следствия; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nорганы внутренних дел;\n\nвойска национальной гвардии Российской Федерации; (В редакции Федерального закона от 03.07.2016 № 229-ФЗ)\n\nорганы юстиции;\n\nсистема исполнения наказаний;\n\nорганы безопасности;\n\nорганы пограничной службы;\n\nабзац; (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nзащита населения и территории от чрезвычайных ситуаций природного и техногенного характера,  пожарная безопасность; (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nгражданская оборона; (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nмиграционная политика;\n\nмодернизация войск национальной гвардии Российской Федерации,  спасательных воинских формирований федерального органа исполнительной власти,  уполномоченного на решение задач в области гражданской обороны,  а также правоохранительных и иных органов; (В редакции федеральных законов от 27.07.2010 № 223-ФЗ; от 03.07.2016 № 229-ФЗ)\n\nприкладные научные исследования в области национальной безопасности и правоохранительной деятельности;\n\nдругие вопросы в области национальной безопасности и правоохранительной деятельности;\n\n4)  национальная экономика:\n\nобщеэкономические вопросы;\n\nтопливно-энергетический комплекс;\n\nисследование и использование космического пространства;\n\nвоспроизводство минерально-сырьевой базы;\n\nсельское хозяйство и рыболовство;\n\nводное хозяйство; (В редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nлесное хозяйство;\n\nтранспорт;\n\nдорожное хозяйство (дорожные фонды) ; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nсвязь и информатика;\n\nприкладные научные исследования в области национальной экономики;\n\nдругие вопросы в области национальной экономики;\n\n5)  жилищно-коммунальное хозяйство:\n\nжилищное хозяйство;\n\nкоммунальное хозяйство;\n\nблагоустройство;\n\nприкладные научные исследования в области жилищно-коммунального хозяйства;\n\nдругие вопросы в области жилищно-коммунального хозяйства;\n\n6)  охрана окружающей среды:\n\nэкологический контроль;\n\nсбор,  удаление отходов и очистка сточных вод;\n\nохрана объектов растительного и животного мира и среды их обитания;\n\nприкладные научные исследования в области охраны окружающей среды;\n\nдругие вопросы в области охраны окружающей среды;\n\n7)  образование:\n\nдошкольное образование;\n\nобщее образование;\n\nдополнительное образование детей; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nсреднее профессиональное образование;\n\nпрофессиональная подготовка,  переподготовка и повышение квалификации;\n\nвысшее образование; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nмолодежная политика; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nприкладные научные исследования в области образования;\n\nдругие вопросы в области образования;\n\n8)  культура,  кинематография: (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nкинематография;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nприкладные научные исследования в области культуры,  кинематографии; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nдругие вопросы в области культуры,  кинематографии; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n9)  здравоохранение: (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nстационарная медицинская помощь;\n\nамбулаторная помощь;\n\nмедицинская помощь в дневных стационарах всех типов;\n\nскорая медицинская помощь;\n\nсанаторно-оздоровительная помощь;\n\nзаготовка,  переработка,  хранение и обеспечение безопасности донорской крови и ее компонентов;\n\nсанитарно-эпидемиологическое благополучие;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nприкладные научные исследования в области здравоохранения; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nдругие вопросы в области здравоохранения; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n10)  социальная политика:\n\nпенсионное обеспечение;\n\nсоциальное обслуживание населения;\n\nсоциальное обеспечение населения;\n\nохрана семьи и детства;\n\nприкладные научные исследования в области социальной политики;\n\nдругие вопросы в области социальной политики;\n\n11)  физическая культура и спорт:\n\nфизическая культура;\n\nмассовый спорт;\n\nспорт высших достижений;\n\nприкладные научные исследования в области физической культуры и спорта;\n\nдругие вопросы в области физической культуры и спорта;\n\n(Подпункт в редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n12)  средства массовой информации:\n\nтелевидение и радиовещание;\n\nпериодическая печать и издательства;\n\nприкладные научные исследования в области средств массовой информации;\n\nдругие вопросы в области средств массовой информации;\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n13)  обслуживание государственного (муниципального)  долга: (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nобслуживание государственного (муниципального)  внутреннего долга; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nобслуживание государственного (муниципального)  внешнего долга; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n14)  межбюджетные трансферты общего характера бюджетам бюджетной системы Российской Федерации: (В редакции Федерального закона от 04.10.2014 № 283-ФЗ)\n\nдотации на выравнивание бюджетной обеспеченности субъектов Российской Федерации и муниципальных образований;\n\nиные дотации;\n\nпрочие межбюджетные трансферты общего характера.\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n4. Перечень разделов,  подразделов,  целевых статей (государственных (муниципальных)  программ и непрограммных направлений деятельности) ,  групп (групп и подгрупп)  видов расходов бюджета утверждается в составе ведомственной структуры расходов бюджета законом (решением)  о бюджете либо в установленных настоящим Кодексом случаях сводной бюджетной росписью соответствующего бюджета. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nЦелевые статьи расходов бюджетов формируются в соответствии с государственными (муниципальными)  программами,  не включенными в государственные (муниципальные)  программы направлениями деятельности органов государственной власти (государственных органов) ,  органов управления государственными внебюджетными фондами,  органов местного самоуправления,  органов местной администрации,  наиболее значимых учреждений науки,  образования,  культуры и здравоохранения,  указанных в ведомственной структуре расходов бюджета (в целях настоящего Кодекса - непрограммные направления деятельности) ,  и (или)  расходными обязательствами,  подлежащими исполнению за счет средств соответствующих бюджетов. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nКаждому публичному нормативному обязательству,  межбюджетному трансферту,  инициативному проекту,  предусмотренному статьей 261 Федерального закона от 6 октября 2003 года № 131-ФЗ \"Об общих принципах организации местного самоуправления в Российской Федерации\",  поддержанному органами местного самоуправления (далее - инициативный проект) ,  присваиваются уникальные коды классификации расходов бюджетов. (В редакции федеральных законов от 30.12.2008 № 310-ФЗ,  от 07.05.2013 № 104-ФЗ,  от 26.07.2019 № 199-ФЗ,  от 20.07.2020 № 216-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов устанавливаются с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса финансовым органом,  осуществляющим составление и организацию исполнения бюджета,  если иное не установлено настоящим Кодексом.  (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов,  финансовое обеспечение которых осуществляется за счет межбюджетных субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  определяются в порядке,  установленном финансовым органом,  осуществляющим составление и организацию исполнения бюджета,  из которого предоставляются указанные межбюджетные субсидии,  субвенции и иные межбюджетные трансферты,  имеющие целевое назначение,  с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 09.04.2009 № 58-ФЗ,  от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов государственных внебюджетных фондов Российской Федерации,  территориальных государственных внебюджетных фондов устанавливаются соответственно Министерством финансов Российской Федерации,  финансовым органом субъекта Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n5. Код вида расходов включает группу,  подгруппу и элемент вида расходов. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n6. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами видов расходов являются:\n\n1)  группа \"Расходы на выплаты персоналу в целях обеспечения выполнения функций государственными (муниципальными)  органами,  казенными учреждениями,  органами управления государственными внебюджетными фондами\":\n\nподгруппа \"Расходы на выплаты персоналу казенных учреждений\";\n\nподгруппа \"Расходы на выплаты персоналу государственных (муниципальных)  органов\";\n\nподгруппа \"Расходы на выплаты персоналу в сфере национальной безопасности,  правоохранительной деятельности и обороны\";\n\nподгруппа \"Расходы на выплаты персоналу государственных внебюджетных фондов\";\n\n2)  группа \"Закупка товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд\": (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Разработка,  закупка и ремонт вооружений,  военной и специальной техники,  продукции производственно-технического назначения и имущества\";\n\nподгруппа \"Закупка товаров,  работ и услуг для обеспечения специальным топливом и горюче-смазочными материалами,  продовольственного и вещевого обеспечения органов в сфере национальной безопасности,  правоохранительной деятельности и обороны\";\n\nподгруппа \"Закупка товаров,  работ и услуг в целях формирования государственного материального резерва\";\n\nподгруппа \"Иные закупки товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд\"; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\n3)  группа \"Социальное обеспечение и иные выплаты населению\":\n\nподгруппа \"Публичные нормативные социальные выплаты гражданам\";\n\nподгруппа \"Социальные выплаты гражданам,  кроме публичных нормативных социальных выплат\";\n\nподгруппа \"Публичные нормативные выплаты гражданам несоциального характера\";\n\nподгруппа \"Стипендии\";\n\nподгруппа \"Премии и гранты\";\n\nподгруппа \"Иные выплаты населению\";\n\n4)  группа \"Капитальные вложения в объекты государственной (муниципальной)  собственности\": (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Бюджетные инвестиции\";\n\nподгруппа \"Субсидии бюджетным и автономным учреждениям,  государственным (муниципальным)  унитарным предприятиям на осуществление капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности или приобретение объектов недвижимого имущества в государственную (муниципальную)  собственность\"; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Бюджетные инвестиции иным юридическим лицам\";\n\n5)  группа \"Межбюджетные трансферты\":\n\nподгруппа \"Дотации\";\n\nподгруппа \"Субсидии\";\n\nподгруппа \"Субвенции\";\n\nподгруппа \"Иные межбюджетные трансферты\";\n\nабзац; (Утратил силу - Федеральный закон от 14.07.2022 № 264-ФЗ)\n\nподгруппа \"Межбюджетные трансферты бюджету Федерального фонда обязательного медицинского страхования\";\n\nподгруппа \"Межбюджетные трансферты бюджету Фонда пенсионного и социального страхования Российской Федерации\"; (В редакции  Федерального закона от 14.07.2022 № 264-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\n6)  группа \"Предоставление субсидий бюджетным,  автономным учреждениям и иным некоммерческим организациям\":\n\nподгруппа \"Субсидии бюджетным учреждениям\";\n\nподгруппа \"Субсидии автономным учреждениям\";\n\nподгруппа \"Субсидии некоммерческим организациям (за исключением государственных (муниципальных)  учреждений,  государственных корпораций (компаний) ,  публично-правовых компаний) \"; (В редакции Федерального закона от 26.07.2019 № 199-ФЗ)\n\n7)  группа \"Обслуживание государственного (муниципального)  долга\":\n\nподгруппа \"Обслуживание государственного долга Российской Федерации\";\n\nподгруппа \"Обслуживание государственного долга субъекта Российской Федерации\";\n\nподгруппа \"Обслуживание муниципального долга\";\n\n8)  группа \"Иные бюджетные ассигнования\":\n\nподгруппа \"Субсидии юридическим лицам (кроме некоммерческих организаций) ,  индивидуальным предпринимателям,  физическим лицам - производителям товаров,  работ,  услуг\";\n\nподгруппа \"Субсидии государственным корпорациям (компаниям) ,  публично-правовым компаниям\"; (В редакции Федерального закона от 18.07.2017 № 178-ФЗ)\n\nподгруппа \"Исполнение судебных актов\";\n\nподгруппа \"Исполнение государственных (муниципальных)  гарантий без права регрессного требования гаранта к принципалу или уступки гаранту прав требования бенефициара к принципалу\";\n\nподгруппа \"Уплата налогов,  сборов и иных платежей\";\n\nподгруппа \"Предоставление платежей,  взносов,  безвозмездных перечислений субъектам международного права\";\n\nподгруппа \"Резервные средства\";\n\nподгруппа \"Специальные расходы\";\n\nподгруппа \"Субсидии юридическим лицам,  индивидуальным предпринимателям,  являющимся стороной концессионных соглашений,  соглашений о государственно-частном партнерстве,  муниципально-частном партнерстве,  а также на финансовое обеспечение (возмещение)  затрат,  связанных с финансовой арендой (лизингом) \". (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n7. Перечень единых для бюджетов бюджетной системы Российской Федерации элементов видов расходов классификации расходов бюджетов устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n8. Министерство финансов Российской Федерации утверждает общие требования к порядку формирования перечня кодов элементов видов расходов классификации расходов бюджетов при дополнительной детализации расходов бюджетов субъектов Российской Федерации (местных бюджетов)  с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n9. Внесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзацах четвертом - шестом пункта 4 настоящей статьи,  осуществляется в связи с внесением изменений в сводную бюджетную роспись федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации и применяется к отношениям,  возникшим с момента внесения изменений в сводную бюджетную роспись соответствующего бюджета. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 23. Классификация источников финансирования дефицитов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2891f6070baecb0ec4a18768898c741fe39b5c6316045620521e0f6b514cd9df"},{"code_id":"BK_RF","article_number":"23.1","version_date":"1998-07-31","article_text":"1. Код классификации операций сектора государственного управления включает группу,  статью и подстатью классификации операций сектора государственного управления. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n2. Едиными для бюджетов бюджетной системы Российской Федерации группами классификации операций сектора государственного управления являются:\n\n1)  доходы;\n\n2)  расходы;\n\n3)  поступление нефинансовых активов;\n\n4)  выбытие нефинансовых активов;\n\n5)  поступление финансовых активов;\n\n6)  выбытие финансовых активов;\n\n7)  увеличение обязательств;\n\n8)  уменьшение обязательств.\n\n(Пункт в редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n3. Единый для бюджетов бюджетной системы Российской Федерации перечень статей и подстатей классификации операций сектора государственного управления устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n4. Порядок применения классификации операций сектора государственного управления устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n5. Министерство финансов Российской Федерации утверждает общие требования к порядку формирования перечня подстатей классификации операций сектора государственного управления при дополнительной детализации операций сектора государственного управления с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 23.1. Классификация операций сектора государственного управления","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d80d3e75f0c784ba964477ef632b25515267d8efc54419812192dd02111bbd37"},{"code_id":"BK_RF","article_number":"24","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 24.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"25","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 25.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"26","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 26.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"27","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 27.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"28","version_date":"1998-07-31","article_text":"Бюджетная система Российской Федерации основана на принципах:\n\nединства бюджетной системы Российской Федерации;\n\nразграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nсамостоятельности бюджетов;\n\nравенства бюджетных прав субъектов Российской Федерации,  муниципальных образований; (Дополнение абзацем - Федеральный закон от 20.08.2004 № 120-ФЗ)\n\nполноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nсбалансированности бюджета;\n\nэффективности использования бюджетных средств; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\nобщего (совокупного)  покрытия расходов бюджетов;\n\nпрозрачности (открытости) ; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nучастия граждан в бюджетном процессе; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nдостоверности бюджета;\n\nадресности и целевого характера бюджетных средств;\n\nподведомственности расходов бюджетов; (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)\n\nединства кассы. (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 28. Перечень принципов бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1576b05a5d73b00a6cfb31520b9d27483b5f7ae80026a88ae712246d1c695e7"},{"code_id":"BK_RF","article_number":"29","version_date":"1998-07-31","article_text":"Принцип единства бюджетной системы Российской Федерации означает единство бюджетного законодательства Российской Федерации,  принципов организации и функционирования бюджетной системы Российской Федерации,  форм бюджетной документации и бюджетной отчетности,  бюджетной классификации Российской Федерации,  бюджетных мер принуждения за нарушение бюджетного законодательства Российской Федерации,  единый порядок установления и исполнения расходных обязательств,  формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации,  ведения бюджетного учета и составления бюджетной отчетности бюджетов бюджетной системы Российской Федерации и казенных учреждений,  единство порядка исполнения судебных актов по обращению взыскания на средства бюджетов бюджетной системы Российской Федерации. (В редакции  федеральных законов от 27.12.2005 № 197-ФЗ,  от 26.04.2007 № 63-ФЗ,  от 08.05.2010 № 83-ФЗ,  от 23.07.2013 № 252-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 29. Принцип единства бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2424db99b59ebe914b7230fab81f7f92abf0f0a294864e7544d058958194f09"},{"code_id":"BK_RF","article_number":"3","version_date":"1998-07-31","article_text":"1. Президент Российской Федерации издает указы,  регулирующие бюджетные правоотношения,  указанные в пункте 1 статьи 1 настоящего Кодекса. Указы Президента Российской Федерации не могут противоречить настоящему Кодексу и федеральным законам,  указанным в статье 2 настоящего Кодекса.\n\n2. На основании и во исполнение настоящего Кодекса,  федеральных законов,  указанных в статье 2 настоящего Кодекса,  указов Президента Российской Федерации,  предусмотренных пунктом 1 настоящей статьи,  Правительство Российской Федерации принимает нормативные правовые акты,  регулирующие бюджетные правоотношения,  предусмотренные статьей 1 настоящего Кодекса.\n\n21. Совет Федерации Федерального Собрания Российской Федерации,  Государственная Дума Федерального Собрания Российской Федерации принимают акты,  регулирующие бюджетные правоотношения,  в случаях,  предусмотренных настоящим Кодексом. (Дополнение пунктом - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\n3. Федеральные органы исполнительной власти принимают акты,  регулирующие бюджетные правоотношения,  предусмотренные статьей 1 настоящего Кодекса,  в случаях и пределах,  которые предусмотрены настоящим Кодексом,  федеральными законами,  указанными в статье 2 настоящего Кодекса,  и актами,  указанными в пунктах 1 и 2 настоящей статьи.\n\n4. Органы государственной власти субъектов Российской Федерации принимают нормативные правовые акты,  регулирующие бюджетные правоотношения,  в пределах своей компетенции в соответствии с настоящим Кодексом.\n\n5. Органы местного самоуправления принимают муниципальные правовые акты,  регулирующие бюджетные правоотношения,  в пределах своей компетенции в соответствии с настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 3. Нормативные правовые акты,  регулирующие бюджетные правоотношения","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ff108cd5f3cc567b4eda41fe9e2e24bca90d8efd4983b08ea5af4456863169e"},{"code_id":"BK_RF","article_number":"30","version_date":"1998-07-31","article_text":"Принцип разграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации означает закрепление в соответствии с законодательством Российской Федерации доходов,  расходов и источников финансирования дефицитов бюджетов за бюджетами бюджетной системы Российской Федерации,  а также определение полномочий органов государственной власти (органов местного самоуправления)  и органов управления государственными внебюджетными фондами по формированию доходов бюджетов,  источников финансирования дефицитов бюджетов и установлению и исполнению расходных обязательств публично-правовых образований.\n\nОрганы государственной власти (органы местного самоуправления)  и органы управления государственными внебюджетными фондами не вправе налагать на юридические и физические лица не предусмотренные законодательством Российской Федерации финансовые и иные обязательства по обеспечению выполнения своих полномочий.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 30. Принцип разграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"773b42ae70b5fd45755d6690b0630b8d599d96131e8e24b03ef1598a957574a1"},{"code_id":"BK_RF","article_number":"31","version_date":"1998-07-31","article_text":"Принцип самостоятельности бюджетов означает:\n\nправо и обязанность органов государственной власти и органов местного самоуправления самостоятельно обеспечивать сбалансированность соответствующих бюджетов и эффективность использования бюджетных средств;\n\nправо и обязанность органов государственной власти и органов местного самоуправления самостоятельно осуществлять бюджетный процесс,  за исключением случаев,  предусмотренных настоящим Кодексом;\n\nправо органов государственной власти и органов местного самоуправления устанавливать в соответствии с законодательством Российской Федерации о налогах и сборах налоги и сборы,  доходы от которых подлежат зачислению в соответствующие бюджеты бюджетной системы Российской Федерации;\n\nправо органов государственной власти и органов местного самоуправления в соответствии с настоящим Кодексом самостоятельно определять формы и направления расходования средств бюджетов (за исключением расходов,  финансовое обеспечение которых осуществляется за счет межбюджетных субсидий и субвенций из других бюджетов бюджетной системы Российской Федерации) ;\n\nнедопустимость установления расходных обязательств,  подлежащих исполнению за счет доходов и источников финансирования дефицитов других бюджетов бюджетной системы Российской Федерации,  а также расходных обязательств,  подлежащих исполнению одновременно за счет средств двух и более бюджетов бюджетной системы Российской Федерации,  за счет средств консолидированных бюджетов или без определения бюджета,  за счет средств которого должно осуществляться исполнение соответствующих расходных обязательств;\n\nправо органов государственной власти и органов местного самоуправления предоставлять средства из бюджета на исполнение расходных обязательств,  устанавливаемых иными органами государственной власти и органами местного самоуправления,  исключительно в форме межбюджетных трансфертов;\n\nнедопустимость введения в действие в течение текущего финансового года органами государственной власти и органами местного самоуправления изменений бюджетного законодательства Российской Федерации и (или)  законодательства о налогах и сборах,  законодательства о других обязательных платежах,  приводящих к увеличению расходов и (или)  снижению доходов других бюджетов бюджетной системы Российской Федерации без внесения изменений в законы (решения)  о соответствующих бюджетах,  предусматривающих компенсацию увеличения расходов,  снижения доходов;\n\nнедопустимость изъятия дополнительных доходов,  экономии по расходам бюджетов,  полученных в результате эффективного исполнения бюджетов.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 31. Принцип самостоятельности бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8874802fabf7ca02043f3d17048e9a79ea3da832eb9f375284c2cae138685d18"},{"code_id":"BK_RF","article_number":"31.1","version_date":"1998-07-31","article_text":"Принцип равенства бюджетных прав субъектов Российской Федерации,  муниципальных образований означает определение бюджетных полномочий органов государственной власти субъектов Российской Федерации и органов местного самоуправления,  установление и исполнение расходных обязательств,  формирование налоговых и неналоговых доходов бюджетов субъектов Российской Федерации и местных бюджетов,  определение объема,  форм и порядка предоставления межбюджетных трансфертов в соответствии с едиными принципами и требованиями,  установленными настоящим Кодексом.\n\nДоговоры и соглашения между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации,  органами государственной власти и органами местного самоуправления,  не соответствующие настоящему Кодексу,  являются недействительными.\n\n(Дополнение статьей - Федеральный закон от 20.08.2004 № 120-ФЗ)  (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 31.1. Принцип равенства бюджетных прав субъектов Российской Федерации,  муниципальных образований","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e02abfe93b41b2e936df7f0d2943c741646edf78fe8b19479627e8e6af6ec82"},{"code_id":"BK_RF","article_number":"32","version_date":"1998-07-31","article_text":"Принцип полноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов означает,  что все доходы,  расходы и источники финансирования дефицитов бюджетов в обязательном порядке и в полном объеме отражаются в соответствующих бюджетах.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 32. Принцип полноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9dcb57efa0a6b4872e958378a98c0ef05f02c8e09a699d88cd4163d462eab01"},{"code_id":"BK_RF","article_number":"33","version_date":"1998-07-31","article_text":"Принцип сбалансированности бюджета означает,  что объем предусмотренных бюджетом расходов должен соответствовать суммарному объему доходов бюджета и поступлений источников финансирования его дефицита,  уменьшенных на суммы выплат из бюджета,  связанных с источниками финансирования дефицита бюджета и изменением остатков на счетах по учету средств бюджетов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nПри составлении,  утверждении и исполнении бюджета уполномоченные органы должны исходить из необходимости минимизации размера дефицита бюджета.","article_title":"Статья 33. Принцип сбалансированности бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87c13c143a288a6f515adbb28c8f81cf267b62901675bc7ebc5d279a3fa10a58"},{"code_id":"BK_RF","article_number":"34","version_date":"1998-07-31","article_text":"(Наименование в редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\nПринцип эффективности использования бюджетных средств означает,  что при составлении и исполнении бюджетов участники бюджетного процесса в рамках установленных им бюджетных полномочий должны исходить из необходимости достижения заданных результатов с использованием наименьшего объема средств (экономности)  и (или)  достижения наилучшего результата с использованием определенного бюджетом объема средств (результативности) . (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)","article_title":"Статья 34. Принцип эффективности использования бюджетных средств","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff1f4cb01689ddfa58c11079840a1f8fb88d0e9c4e7e4b76219b8d690e7de644"},{"code_id":"BK_RF","article_number":"35","version_date":"1998-07-31","article_text":"Принцип общего (совокупного)  покрытия расходов бюджетов означает,  что расходы бюджета не могут быть увязаны с определенными доходами бюджета и источниками финансирования дефицита бюджета,  если иное не предусмотрено законом (решением)  о бюджете в части,  касающейся:\n\nсубвенций и субсидий,  полученных из других бюджетов бюджетной системы Российской Федерации;\n\nсредств целевых иностранных кредитов,  бюджетных кредитов из федерального бюджета бюджету субъекта Российской Федерации на финансовое обеспечение реализации инфраструктурных проектов и бюджетных кредитов,  указанных в пункте 1 статьи 939 настоящего Кодекса; (В редакции  федеральных законов от 02.08.2019 № 278-ФЗ,  от 28.06.2021 № 228-ФЗ,  от 26.12.2024 № 488-ФЗ)\n\nдобровольных взносов,  пожертвований,  а также средств самообложения граждан,  инициативных платежей,  предусмотренных статьями 56 и 561 Федерального закона от 6 октября 2003 года № 131-ФЗ \"Об общих принципах организации местного самоуправления в Российской Федерации\" (далее соответственно - средства самообложения граждан,  инициативные платежи) ; (В редакции Федерального закона от 20.07.2020 № 216-ФЗ)\n\nрасходов бюджета,  осуществляемых в соответствии с международными договорами (соглашениями)  с участием Российской Федерации;\n\nрасходов бюджета,  осуществляемых за пределами территории Российской Федерации;\n\nотдельных видов неналоговых доходов,  предлагаемых к введению (отражению в бюджете)  начиная с очередного финансового года;\n\nрасходов бюджета,  осуществляемых в случаях и в пределах поступления отдельных видов неналоговых доходов. (Дополнение абзацем - Федеральный закон от 25.12.2012 № 268-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 35. Принцип общего (совокупного)  покрытия расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d7f422dd2648221cad067a8284ccbafb902c35d3cc49f23d79105fb2f2d89ff"},{"code_id":"BK_RF","article_number":"36","version_date":"1998-07-31","article_text":"Принцип прозрачности (открытости)  означает:\n\nобязательное опубликование в средствах массовой информации утвержденных бюджетов и отчетов об их исполнении,  полноту представления информации о ходе исполнения бюджетов,  а также доступность иных сведений о бюджетах по решению законодательных (представительных)  органов государственной власти,  представительных органов муниципальных образований;\n\nобязательную открытость для общества и средств массовой информации проектов бюджетов,  внесенных в законодательные (представительные)  органы государственной власти (представительные органы муниципальных образований) ,  процедур рассмотрения и принятия решений по проектам бюджетов,  в том числе по вопросам,  вызывающим разногласия либо внутри законодательного (представительного)  органа государственной власти (представительного органа муниципального образования) ,  либо между законодательным (представительным)  органом государственной власти (представительным органом муниципального образования)  и исполнительным органом государственной власти (местной администрацией) ;\n\nобеспечение доступа к информации,  размещенной в информационно-телекоммуникационной сети \"Интернет\" на едином портале бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\nстабильность и (или)  преемственность бюджетной классификации Российской Федерации,  а также обеспечение сопоставимости показателей бюджета отчетного,  текущего и очередного финансового года (очередного финансового года и планового периода) .\n\nСекретные статьи могут утверждаться только в составе федерального бюджета.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 36. Принцип прозрачности (открытости)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f36b62f72870e8a9e1019f7d69e9a5db6e43b5e40d639023b5aa975599c9ff3"},{"code_id":"BK_RF","article_number":"37","version_date":"1998-07-31","article_text":"Принцип достоверности бюджета означает надежность показателей прогноза социально-экономического развития соответствующей территории и реалистичность расчета доходов и расходов бюджета.","article_title":"Статья 37. Принцип достоверности бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d34e50a098dfac797d327235197cbf6c680e527623f24940ef72709ac582e665"},{"code_id":"BK_RF","article_number":"38","version_date":"1998-07-31","article_text":"Принцип адресности и целевого характера бюджетных средств означает,  что бюджетные ассигнования и лимиты бюджетных обязательств доводятся до конкретных получателей бюджетных средств с указанием цели их использования.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 38. Принцип адресности и целевого характера бюджетных средств","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f1242ac60e41de85fc9281cfeb475efbab30c04bbf83366cd30e157e28dee233"},{"code_id":"BK_RF","article_number":"38.1","version_date":"1998-07-31","article_text":"Принцип подведомственности расходов бюджетов означает,  что получатели бюджетных средств вправе получать бюджетные ассигнования и лимиты бюджетных обязательств только от главного распорядителя (распорядителя)  бюджетных средств,  в ведении которого они находятся.\n\nГлавные распорядители (распорядители)  бюджетных средств не вправе распределять бюджетные ассигнования и лимиты бюджетных обязательств распорядителям и получателям бюджетных средств,  не включенным в перечень подведомственных им распорядителей и получателей бюджетных средств в соответствии со статьей 158 настоящего Кодекса.\n\nРаспорядитель и получатель бюджетных средств могут быть включены в перечень подведомственных распорядителей и получателей бюджетных средств только одного главного распорядителя бюджетных средств.\n\nПодведомственность получателя бюджетных средств главному распорядителю (распорядителю)  бюджетных средств возникает в силу закона,  нормативного правового акта Президента Российской Федерации,   Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации. (В редакции  федеральных законов от 30.12.2008 № 310-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 38.1. Принцип подведомственности расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2816e0d2d9ebeb437f499e64d8071dd94ed3417eddcb07edc24c0eab7e89f2c"},{"code_id":"BK_RF","article_number":"38.2","version_date":"1998-07-31","article_text":"Принцип единства кассы означает зачисление всех поступлений в бюджет на единый счет бюджета и осуществление всех перечислений из бюджета с единого счета бюджета,  за исключением операций по исполнению бюджетов,  осуществляемых за пределами территории Российской Федерации в соответствии с нормативными правовыми актами Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)  (В редакции Федерального закона от 27.12.2019 № 479-ФЗ)","article_title":"Статья 38.2. Принцип единства кассы","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a686743581f9b02ad2239e84e0aeda2ebc76dd89e4673966c095e3b86c0a5f8"},{"code_id":"BK_RF","article_number":"39","version_date":"1998-07-31","article_text":"Доходы бюджетов формируются в соответствии с бюджетным законодательством Российской Федерации,  законодательством о налогах и сборах и законодательством об иных обязательных платежах.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 39. Формирование доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d7aba55bae6cc326dac0efa48ffd570613291bf1074a39b13de6ccc1ca64979"},{"code_id":"BK_RF","article_number":"4","version_date":"1998-07-31","article_text":"1. Если международным договором Российской Федерации установлены иные правила,  чем те,  которые предусмотрены бюджетным законодательством Российской Федерации,  применяются правила международного договора.\n\n2. Международные договоры Российской Федерации применяются к бюджетным правоотношениям,  указанным в статье 1 настоящего Кодекса,  непосредственно,  за исключением случаев,  когда из международных договоров следует,  что для их применения требуется издание внутригосударственных актов.","article_title":"Статья 4. Бюджетное законодательство Российской Федерации и нормы международного права","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d599d803633bb233ae89e62575983b057cc5bfffe5c16d0a3aed0de3e7b55a82"},{"code_id":"BK_RF","article_number":"40","version_date":"1998-07-31","article_text":"1. Доходы от федеральных налогов и сборов,  региональных налогов,  местных налогов и сборов,  страховых взносов на обязательное социальное страхование,  иных обязательных платежей,  других поступлений,  являющихся источниками форм\n\nнкта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых источников финансирования дефицитов бюджетов,  а также в связи с внесением изменений в сводную бюджетную роспись по источникам финансирования дефицита федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации. Указанные изменения в связи с внесением изменений в сводную бюджетную роспись по источникам финансирования дефицита федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации применяются с момента внесения изменений в сводную бюджетную роспись. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n6. Финансовый орган субъекта Российской Федерации утверждает перечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы государственной власти субъектов Российской Федерации,  органы управления территориальными государственными внебюджетными фондами и (или)  находящиеся в их ведении казенные учреждения. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n7. Финансовый орган муниципального образования утверждает перечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы местного самоуправления и (или)  находящиеся в их ведении казенные учреждения. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 40. Зачисление доходов в бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13d1005d9becd35ce91e74c26c179269dbd638ad2b26ae33df8b55884edd7a6b"},{"code_id":"BK_RF","article_number":"40.1","version_date":"1998-07-31","article_text":"1. Излишне уплаченный (взысканный)  платеж в бюджет подлежит возврату по заявлению плательщика платежей в бюджет или подразделения судебных приставов территориального органа Федеральной службы судебных приставов (центрального аппарата Федеральной службы судебных приставов) ,  на исполнении в котором находилось исполнительное производство о взыскании платежей в бюджет,  в течение 30 календарных дней со дня регистрации такого заявления администратором доходов бюджета,  осуществляющим бюджетные полномочия по принятию решения о возврате излишне уплаченных (взысканных)  платежей в бюджет,  если иное не предусмотрено законодательными актами Российской Федерации. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n2. Заявление о возврате излишне уплаченного (взысканного)  платежа в бюджет может быть подано плательщиком платежей в бюджет или подразделением судебных приставов территориального органа Федеральной службы судебных приставов (центрального аппарата Федеральной службы судебных приставов) ,  на исполнении в котором находилось исполнительное производство о взыскании платежей в бюджет,  в течение трех лет со дня уплаты (взыскания)  такого платежа,  если иное не предусмотрено законодательными актами Российской Федерации. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n21. В случае отмены или изменения судебного акта,  акта органа или должностного лица,  на основании которых был выдан исполнительный документ,  отмены или признания недействительным исполнительного документа заявление о возврате излишне уплаченного (взысканного)  платежа в бюджет может быть подано плательщиком платежей в бюджет в течение трех лет со дня отмены или изменения судебного акта,  акта органа или должностного лица,  на основании которых был выдан исполнительный документ,  отмены или признания недействительным исполнительного документа. (Дополнение пунктом - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n3. Возврат излишне уплаченных (взысканных)  платежей в бюджет осуществляется в соответствии с общими требованиями,  установленными Министерством финансов Российской Федерации.\n\n4. Положения настоящей статьи не распространяются на платежи,  предусмотренные законодательством о налогах и сборах,  законодательством Российской Федерации об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний,  правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании,  а также на безвозмездные поступления. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n5. Возврат излишне уплаченных (взысканных)  платежей в бюджет в рамках исполнения денежных обязательств перед публично-правовыми образованиями осуществляется в соответствии с договорами и (или)  гражданским законодательством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 01.07.2021 № 244-ФЗ)","article_title":"Статья 40.1. Возврат излишне уплаченных (взысканных)  платежей в бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55c60c071418beb90353a426f624f3894eee176e4ebb66a7d867dfe89596231b"},{"code_id":"BK_RF","article_number":"41","version_date":"1998-07-31","article_text":"1. К доходам бюджетов относятся налоговые доходы,  неналоговые доходы и безвозмездные поступления.\n\n2. К налоговым доходам бюджетов относятся доходы от предусмотренных законодательством Российской Федерации о налогах и сборах федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных налогов,  местных налогов и сборов,  а также пеней и штрафов по ним. (В редакции Федерального закона от 03.11.2015 № 301-ФЗ)\n\n3. К неналоговым доходам бюджетов относятся:\n\nдоходы от использования имущества,  находящегося в государственной или муниципальной собственности,  за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\"; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\nдоходы от продажи имущества (кроме акций и иных форм участия в капитале,  государственных запасов драгоценных металлов и драгоценных камней) ,  находящегося в государственной или муниципальной собственности,  за исключением движимого имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\"; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 28.12.2013 № 418-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\nдоходы от платных услуг,  оказываемых казенными учреждениями; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nсредства,  полученные в результате применения мер гражданско-правовой,  административной и уголовной ответственности,  в том числе штрафы,  конфискации,  компенсации,  а также средства,  полученные в возмещение вреда,  причиненного Российской Федерации,  субъектам Российской Федерации,  муниципальным образованиям,  и иные суммы принудительного изъятия;\n\nсредства самообложения граждан,  инициативные платежи; (В редакции Федерального закона от 20.07.2020 № 216-ФЗ)\n\nиные неналоговые доходы.\n\n4. К безвозмездным поступлениям относятся:\n\nдотации из других бюджетов бюджетной системы Российской Федерации;\n\nсубсидии из других бюджетов бюджетной системы Российской Федерации (межбюджетные субсидии) ;\n\nсубвенции из федерального бюджета и (или)  из бюджетов субъектов Российской Федерации;\n\nиные межбюджетные трансферты из других бюджетов бюджетной системы Российской Федерации;\n\nбезвозмездные поступления от физических и юридических лиц,  международных организаций и правительств иностранных государств,  в том числе добровольные пожертвования.\n\n5. Доходы от использования имущества,  находящегося в государственной или муниципальной собственности,  и платных услуг,  оказываемых казенными учреждениями,  средства безвозмездных поступлений и иной приносящей доход деятельности при составлении,  утверждении,  исполнении бюджета и составлении отчетности о его исполнении включаются в состав доходов бюджета. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n6. Нормативные правовые акты,  муниципальные правовые акты,  договоры,  в соответствии с которыми уплачиваются платежи,  являющиеся источниками неналоговых доходов бюджетов,  должны предусматривать положения о порядке их исчисления,  размерах,  сроках и (или)  об условиях их уплаты. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 41. Виды доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdd1b3740382bcc3d6fbb3966536b7be5e6d180a16ac6db2feb8ab250b2567f4"},{"code_id":"BK_RF","article_number":"42","version_date":"1998-07-31","article_text":"К доходам бюджетов от использования имущества,  находящегося в государственной или муниципальной собственности,  относятся:\n\nдоходы,  получаемые в виде арендной либо иной платы за передачу в возмездное пользование государственного и муниципального имущества,  за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\"; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\nсредства,  получаемые в виде процентов по остаткам бюджетных средств на счетах в Центральном банке Российской Федерации и в кредитных организациях;\n\nсредства,  получаемые от передачи имущества,  находящегося в государственной или муниципальной собственности (за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  и имущества,  переданного в доверительное управление юридическим лицам,  созданным в организационно-правовой форме государственной компании) ,  в залог,  в доверительное управление; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nплата за пользование бюджетными кредитами;\n\nдоходы в виде прибыли,  приходящейся на доли в уставных (складочных)  капиталах хозяйственных товариществ и обществ,  или дивидендов по акциям,  принадлежащим Российской Федерации,  субъектам Российской Федерации или муниципальным образованиям,  за исключением случаев,  установленных федеральными законами; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nчасть прибыли государственных и муниципальных унитарных предприятий,  остающаяся после уплаты налогов и иных обязательных платежей;\n\nдругие предусмотренные законодательством Российской Федерации доходы от использования имущества,  находящегося в государственной или муниципальной собственности,  за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\". (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 42. Доходы от использования имущества,  находящегося в государственной или муниципальной собственности","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58b3e5b97b4aa273ddc7615ccda223279ba39e85d23ea32036c78288cf6894a8"},{"code_id":"BK_RF","article_number":"43","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 43.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"44","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 44.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"45","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 45.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"46","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 04.11.2022 № 432-ФЗ)\n\n1. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов в случае,  если постановления о наложении административных штрафов вынесены:\n\n1)  судьями федеральных судов (если иное не установлено пунктами 3,  5 - 53 и 6 настоящей статьи) ; (В редакции  федеральных законов от 01.07.2021 № 244-ФЗ,  от 24.06.2025 № 158-ФЗ)\n\n2)  должностными лицами федеральных органов исполнительной власти,  их структурных подразделений,  территориальных органов и структурных подразделений территориальных органов,  иных федеральных государственных органов (если иное не установлено пунктами 3,  31,  5 и 6 настоящей статьи) ; (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n3)  должностными лицами Центрального банка Российской Федерации;\n\n4)  должностными лицами государственных учреждений,  подведомственных федеральным органам исполнительной власти.\n\n2. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов в случае,  если постановления о наложении административных штрафов вынесены:\n\n1)  должностными лицами исполнительных органов субъектов Российской Федерации (если иное не установлено пунктами 5 и 6 настоящей статьи) ; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n2)  должностными лицами государственных учреждений,  подведомственных исполнительным органам субъектов Российской Федерации. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n3. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за нарушение Правил дорожного движения,  правил эксплуатации транспортного средства,  подлежат зачислению:\n\n1)  в федеральный бюджет - по нормативу 25 процентов;\n\n2)  в бюджет субъекта Российской Федерации по месту нахождения должностного лица федерального органа исполнительной власти,  органа прокуратуры Российской Федерации или исполнительного органа субъекта Российской Федерации,  принявшего решение о наложении административного штрафа или направившего дело об административном правонарушении на рассмотрение судье,  в комиссию по делам несовершеннолетних и защите их прав,  - по нормативу 75 процентов.\n\n(Пункт в редакции  Федерального закона от 26.12.2024 № 488-ФЗ)\n\n31. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за нарушения правил движения тяжеловесного и (или)  крупногабаритного транспортного средства,  выявленные при осуществлении весового и габаритного контроля транспортных средств на автомобильных дорогах общего пользования регионального или межмуниципального,  местного значения,  если постановления о наложении указанных административных штрафов вынесены должностными лицами,  указанными в подпункте 2 пункта 1 настоящей статьи,  по результатам рассмотрения дел об административных правонарушениях,  подлежат зачислению в бюджеты субъектов Российской Федерации,  на территориях которых расположены соответствующие автомобильные дороги,  по нормативу 100 процентов. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n4. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях,  в случае,  если постановления о наложении административных штрафов вынесены мировыми судьями,  комиссиями по делам несовершеннолетних и защите их прав,  подлеж\n\nналогов и сборов,  региональных налогов,  местных налогов и сборов,  страховых взносов на обязательное социальное страхование,  иных обязательных платежей,  других поступлений,  являющихся источниками формирования доходов бюджетов бюджетной системы Российской Федерации,  зачисляются на казначейские счета для осуществления и отражения операций по учету и распределению поступлений,  за исключением случаев,  установленных настоящим Кодексом,  для их распределения органами Федерального казначейства в соответствии с нормативами,  установленными настоящим Кодексом,  законом (решением)  о бюджете и иными законами субъектов Российской Федерации и муниципальными правовыми актами,  принятыми в соответствии с положениями настоящего Кодекса,  между федеральным бюджетом,  бюджетами субъектов Российской Федерации,  местными бюджетами,  а также бюджетами государственных внебюджетных фондов в случаях,  предусмотренных законодательством Российской Федерации. (В редакции федеральных законов от 24.07.2009 № 213-ФЗ,  от 03.11.2015 № 301-ФЗ,  от 27.12.2019 № 479-ФЗ)\n\nОрганы Федерального казначейства осуществляют в установленном Министерством финансов Российской Федерации порядке учет доходов,  поступивших в бюджетную систему Российской Федерации,  и их распределение между бюджетами в соответствии с кодом бюджетной классификации Российской Федерации,  указанным в расчетном документе,  распоряжении о совершении казначейского платежа (далее - распоряжение)  на зачисление средств на счет,  указанный в абзаце первом настоящего пункта,  а в случае возврата (зачета,  уточнения)  платежа соответствующим администратором доходов бюджета - согласно представленному им распоряжению,  а также направляют информацию о зачислении (зачете,  возврате)  денежных средств,  об уточнении вида и принадлежности платежа в Государственную информационную систему о государственных и муниципальных платежах. (В редакции  федеральных законов от 04.11.2022 № 432-ФЗ,  от 21.11.2022 № 448-ФЗ)\n\nОрганы Федерального казначейства не позднее следующего рабочего дня после зачисления поступлений от доходов,  указанных в абзаце первом настоящего пункта,  на казначейские счета для осуществления и отражения операций по учету и распределению поступлений,  получения распоряжений налогового органа о зачете единого налогового платежа,  предусмотренного Налоговым кодексом Российской Федерации (далее - единый налоговый платеж) ,  в счет уплаты налогов,  авансовых платежей по налогам,  сборов,  страховых взносов,  пеней,  штрафов,  процентов,  предусмотренных законодательством Российской Федерации о налогах и сборах,  получения распоряжений таможенного органа для проведения операций,  связанных с авансовым платежом,  предусмотренным в отношении обязательных платежей правом Евразийского экономического союза и законодательством Российской Федерации,  и операций,  связанных с денежным залогом,  предусмотренным правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании,  осуществляют перечисление указанных доходов на единые счета соответствующих бюджетов. (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nПо запросу финансовых органов органы Федерального казначейства предоставляют информацию из расчетных документов,  указанных в абзаце втором настоящего пункта,  о поступивших от юридических лиц платежах,  являющихся источниками формирования доходов соответствующего бюджета (в том числе консолидированного бюджета субъекта Российской Федерации,  консолидированного бюджета муниципального района,  консолидированного бюджета городского округа с внутригородским делением) ,  за исключением информации об операциях,  связанных с единым налоговым платежом. (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nПо запросам финансовых органов,  органов Федерального казначейства налоговые органы предоставляют сведения в разрезе юридических лиц о принадлежности денежных средств,  перечисленных и (или)  признаваемых в качестве единого налогового платежа,  определенной в соответствии со статьей 45 Налогового кодекса Российской Федерации,  к налогам,  сборам,  страховым взносам,  являющимся источниками формирования доходов соответствующего бюджета (в том числе консолидированного бюджета субъекта Российской Федерации,  консолидированного бюджета муниципального района,  консолидированного бюджета городского округа с внутригородским делением,  бюджета государственного внебюджетного фонда) . (Дополнение абзацем - Федеральный закон от 04.11.2022 № 432-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n2. Денежные средства считаются поступившими в доходы соответствующего бюджета бюджетной системы Российской Федерации с момента их зачисления на единый счет этого бюджета.\n\n3. Денежные средства,  в отношении которых отсутствует информация,  позволяющая однозначно определить их принадлежность к виду (подвиду)  дохода бюджета,  закрепляемому за администратором доходов бюджета,  либо к единому налоговому платежу,  либо к авансовому платежу,  предусмотренному в отношении обязательных платежей правом Евразийского экономического союза и законодательством Российской Федерации,  либо к денежному залогу,  предусмотренному правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании,  относятся органами Федерального казначейства к невыясненным поступлениям,  зачисляемым в соответствующий бюджет. (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nНевыясненные поступления,  зачисленные в бюджеты бюджетной системы Российской Федерации,  подлежат возврату (уточнению)  не позднее трех лет со дня их зачисления на единый счет соответствующего бюджета.\n\nПо истечении срока,  указанного в абзаце втором настоящего пункта,  невыясненные поступления,  которые зачислены в бюджеты бюджетной системы Российской Федерации и по которым не осуществлен возврат (уточнение) ,  подлежат отражению по коду классификации доходов бюджетов,  предусмотренному для учета прочих неналоговых доходов соответствующего бюджета бюджетной системы Российской Федерации,  и возврату (уточнению)  не подлежат.\n\n(Дополнение пунктом - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 46. Доходы бюджетов от штрафов,  неустоек,  пеней,  процентов и платежей,  поступающих от реализации конфискованного имущества,  компенсации ущерба,  возмещения вреда окружающей среде","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4101db8fdcf409c36460bd4d09628a43da5bc7aaa5427edb49c672b25caa9152"},{"code_id":"BK_RF","article_number":"47","version_date":"1998-07-31","article_text":"К собственным доходам бюджетов относятся:\n\nналоговые доходы,  зачисляемые в бюджеты в соответствии с бюджетным законодательством Российской Федерации и законодательством о налогах и сборах;\n\nненалоговые доходы,  зачисляемые в бюджеты в соответствии с законодательством Российской Федерации,  законами субъектов Российской Федерации и муниципальными правовыми актами представительных органов муниципальных образований; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nдоходы,  полученные бюджетами в виде безвозмездных поступлений,  за исключением субвенций. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 47. Собственные доходы бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fb986d8197077bce09f6c8812177882cdd1ea324e2dc094dc0940683b6c67c29"},{"code_id":"BK_RF","article_number":"47.1","version_date":"1998-07-31","article_text":"1. Министерство финансов Российской Федерации,  органы управления государственными внебюджетными фондами,  финансовые органы субъектов Российской Федерации и муниципальных образований обязаны вести реестры источников доходов бюджетов бюджетной системы Российской Федерации.\n\n2. Под перечнем источников доходов Российской Федерации понимается свод (перечень)  федеральных налогов и сборов,  региональных и местных налогов,  страховых взносов на обязательное социальное страхование,  иных обязательных платежей,  других поступлений,  являющихся источниками формирования доходов бюджетов бюджетной системы Российской Федерации,  с указанием правовых оснований их возникновения,  порядка расчета (размеры,  ставки,  льготы)  и иных характеристик источников доходов бюджетов бюджетной системы Российской Федерации,  определяемых порядком формирования и ведения перечня источников доходов Российской Федерации. (В редакции Федерального закона от 01.07.2021 № 244-ФЗ)\n\n3. Под реестром источников доходов бюджета понимается свод информации о доходах бюджета по источникам доходов бюджетов бюджетной системы Российской Федерации,  формируемой в процессе составления,  утверждения и исполнения бюджета,  на основании перечня источников доходов Российской Федерации.\n\n4. Реестр источников доходов Российской Федерации включает реестр источников доходов федерального бюджета,  реестры источников доходов бюджетов субъектов Российской Федерации,  реестры источников доходов местных бюджетов и реестры источников доходов бюджетов государственных внебюджетных фондов.\n\n5. Состав информации,  порядок формирования и ведения перечня источников доходов Российской Федерации,  общие требования к составу информации,  порядку формирования и ведения реестра источников доходов Российской Федерации,  реестра источников доходов федерального бюджета,  реестров источников доходов бюджетов субъектов Российской Федерации,  реестров источников доходов местных бюджетов и реестров источников доходов бюджетов государственных внебюджетных фондов определяются Правительством Российской Федерации.\n\n6. Реестр источников доходов Российской Федерации,  реестр источников доходов федерального бюджета и реестры источников доходов бюджетов государственных внебюджетных фондов Российской Федерации формируются и ведутся в порядке,  установленном Министерством финансов Российской Федерации.\n\n7. Реестры источников доходов бюджетов субъектов Российской Федерации,  реестры источников доходов бюджетов территориальных государственных внебюджетных фондов и реестры источников доходов местных бюджетов формируются и ведутся в порядке,  установленном соответственно высшим исполнительным органом субъекта Российской Федерации и местной администрацией. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n8. Реестр источников доходов бюджета субъекта Российской Федерации,  а также свод реестров источников доходов бюджетов муниципальных образований,  входящих в состав субъекта Российской Федерации,  и реестр источников доходов бюджета территориального государственного внебюджетного фонда представляются финансовым органом субъекта Российской Федерации в Министерство финансов Российской Федерации в порядке,  установленном Министерством финансов Российской Федерации.\n\n9. Реестры источников доходов бюджетов муниципальных образований,  входящих в состав субъекта Российской Федерации,  и реестр источников доходов бюджета территориального государственного внебюджетного фонда представляются в финансовый орган субъекта Российской Федерации в порядке,  установленном высшим исполнительным органом субъекта Российской Федерации. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 22.10.2014 № 311-ФЗ)","article_title":"Статья 47.1. Перечень и реестры источников доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"384dc0647ee3c7f39ee4e329af4dc21bbd7915411ae7fa33cf940cfe99d84394"},{"code_id":"BK_RF","article_number":"47.2","version_date":"1998-07-31","article_text":"1. Платежи в бюджет,  не уплаченные в установленный срок (задолженность по платежам в бюджет) ,  признаются безнадежными к взысканию в случае:\n\n1)  смерти физического лица - плательщика платежей в бюджет или объявления его умершим в порядке,  установленном гражданским процессуальным законодательством Российской Федерации;\n\n2)  завершения процедуры банкротства гражданина,  индивидуального предпринимателя в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве) \" - в части задолженности по платежам в бюджет,  от и\n\nерации об административных правонарушениях,  в случае,  если постановления о наложении административных штрафов вынесены мировыми судьями,  комиссиями по делам несовершеннолетних и защите их прав,  подлежат зачислению (если иное не установлено пунктами 3,  5 - 52 и 6 настоящей статьи) : (В редакции федеральных законов от 31.07.2020 № 263-ФЗ,  от 01.07.2021 № 244-ФЗ)\n\n1)  в бюджет субъекта Российской Федерации по нормативу 50 процентов;\n\n2)  в бюджет муниципального района,  муниципального округа,  городского округа,  городского округа с внутригородским делением (по месту нахождения органа или должностного лица,  принявших решение о наложении административного штрафа)  по нормативу 50 процентов. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\n5. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные должностными лицами органов муниципального контроля,  подлежат зачислению в бюджеты муниципальных образований,  за счет средств бюджетов которых осуществляется финансовое обеспечение деятельности указанных органов,  по нормативу 100 процентов.\n\n51. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные должностными лицами государственных внебюджетных фондов,  подлежат зачислению в бюджеты соответствующих внебюджетных фондов по нормативу 100 процентов. (Дополнение пунктом - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\n52. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные инспекторами Счетной палаты Российской Федерации,  должностными лицами контрольно-счетных органов субъектов Российской Федерации,  подлежат зачислению соответственно в федеральный бюджет,  бюджеты субъектов Российской Федерации по нормативу 100 процентов (если иное не установлено пунктом 6 настоящей статьи) . (Дополнение пунктом - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\n53. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные исполнительными органами субъектов Российской Федерации,  осуществляющими государственный надзор за состоянием,  содержанием,  сохранением,  использованием,  популяризацией и государственной охраной объектов культурного наследия,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов (если иное не установлено пунктом 4 настоящей статьи) . (Дополнение пунктом - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n6. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения в области финансов,  связанные с нецелевым использованием бюджетных средств,  невозвратом либо несвоевременным возвратом бюджетного кредита,  неперечислением либо несвоевременным перечислением платы за пользование бюджетным кредитом,  нарушением условий предоставления бюджетного кредита,  нарушением порядка и (или)  условий предоставления (расходования)  межбюджетных трансфертов,  нарушением условий предоставления бюджетных инвестиций,  субсидий юридическим лицам,  индивидуальным предпринимателям и физическим лицам,  подлежат зачислению в бюджеты бюджетной системы Российской Федерации,  из которых были предоставлены соответствующие бюджетные средства,  бюджетные кредиты,  межбюджетные трансферты,  бюджетные инвестиции,  субсидии,  по нормативу 100 процентов.\n\n7. Суммы административных штрафов,  установленных законами субъектов Российской Федерации:\n\n1)  за нарушение законов и иных нормативных правовых актов субъектов Российской Федерации,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов;\n\n2)  за нарушение муниципальных правовых актов,  подлежат зачислению в бюджеты муниципальных образований по нормативу 100 процентов.\n\n8. В бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя подлежат зачислению суммы административных штрафов,  подлежащие в соответствии с настоящей статьей зачислению в местные бюджеты и бюджеты субъектов Российской Федерации.\n\n9. Суммы штрафов (судебных штрафов) ,  установленных Уголовным кодексом Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n10. Суммы судебных штрафов (денежных взысканий) ,  налагаемых судами в случаях,  предусмотренных Арбитражным процессуальным кодексом Российской Федерации,  Гражданским процессуальным кодексом Российской Федерации,  Кодексом административного судопроизводства Российской Федерации,  Уголовно-процессуальным кодексом Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n11. Суммы штрафов,  пеней,  процентов,  установленных Налоговым кодексом Российской Федерации,  подлежат зачислению в бюджеты бюджетной системы Российской Федерации в следующем порядке:\n\n1)  суммы штрафов,  исчисляемых исходя из сумм (ставок)  налогов (сборов,  страховых взносов) ,  предусмотренных законодательством Российской Федерации о налогах и сборах,  - в бюджеты бюджетной системы Российской Федерации по нормативам отчислений,  установленным бюджетным законодательством Российской Федерации применительно к соответствующим налогам (сборам,  страховым взносам) ;\n\nсуммы пеней - в федеральный бюджет по нормативу 40 процентов,  в бюджет субъекта Российской Федерации по нормативу 43 процента с последующим распределением в текущем финансовом году Федеральным казначейством между бюджетами субъектов Российской Федерации в соответствии с федеральным законом о федеральном бюджете,  в бюджеты государственных внебюджетных фондов Российской Федерации по нормативу 17 процентов с последующим распределением в соответствии со статьей 146 настоящего Кодекса;\n\nсуммы процентов - в федеральный бюджет по нормативу 100 процентов;\n\n2)  суммы иных штрафов - в федеральный бюджет по нормативу 100 процентов.\n\n(Пункт в редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\n12. Суммы штрафов,  пеней,  исчисляемых исходя из сумм страховых взносов на обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний,  взносов,  уплачиваемых организациями в соответствии с федеральными законами на выплату доплаты к пенсии,  подлежат зачислению в бюджеты государственных внебюджетных фондов Российской Федерации,  в которые зачисляются указанные взносы,  по нормативу 100 процентов.\n\n13. Пени и проценты,  установленные правом Евразийского экономического союза и (или)  законодательством Российской Федерации о таможенном регулировании,  начисленные на неуплаченные ввозные таможенные пошлины,  налоги,  антидемпинговые,  специальные и компенсационные пошлины,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  если иное не установлено правом Евразийского экономического союза.\n\n14. Пени и проценты,  установленные правом Евразийского экономического союза и (или)  законодательством Российской Федерации о таможенном регулировании,  начисленные на неуплаченные вывозные таможенные пошлины,  таможенные сборы,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n15. Пени,  установленные правом Евразийского экономического союза и (или)  законодательством Российской Федерации о таможенном регулировании,  начисленные на неуплаченные таможенные пошлины,  налоги,  взимаемые по единым ставкам,  таможенные пошлины,  налоги,  взимаемые в виде совокупного таможенного платежа,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n16. Суммы штрафов,  неустоек,  пеней,  которые должны быть уплачены юридическим или физическим лицом в соответствии с законом или договором в случае неисполнения или ненадлежащего исполнения обязательств перед государственным (муниципальным)  органом,  государственным внебюджетным фондом,  казенным учреждением,  подлежат зачислению в бюджет бюджетной системы Российской Федерации,  получателем средств которого являются указанные орган,  учреждение,  по нормативу 100 процентов. (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nСуммы штрафов,  неустоек,  пеней,  которые должны быть уплачены юридическим или физическим лицом в случае неисполнения или ненадлежащего исполнения поставщиком (подрядчиком,  исполнителем)  обязательств,  предусмотренных государственным контрактом,  заключенным государственной корпорацией,  публично-правовой компанией,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\n17. Денежные средства,  обращенные в собственность государства на основании обвинительных приговоров и постановлений судов,  вынесенных при производстве по уголовным делам,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  за исключением случаев,  установленных настоящим Кодексом. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nДенежные средства,  изымаемые в собственность Российской Федерации,  субъектов Российской Федерации,  городских,  сельских поселений,  муниципальных районов,  муниципальных округов,  городских округов,  внутригородских территорий (внутригородских муниципальных образований)  городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  городских округов с внутригородским делением,  внутригородских районов в соответствии с решениями судов в случае,  не предусмотренном абзацем первым настоящего пункта,  подлежат зачислению соответственно в федеральный бюджет,  бюджеты субъектов Российской Федерации,  городских,  сельских поселений,  муниципальных районов,  муниципальных округов,  городских округов,  внутригородских территорий (внутригородских муниципальных образований)  городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  городских округов с внутригородским делением,  внутригородских районов по нормативу 100 процентов. (В редакции  федеральных законов от 01.10.2020 № 311-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n18. Денежные средства,  полученные от реализации конфискованного имущества,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  если иное не установлено пунктами 17,  19 и 20 настоящей статьи.\n\n19. Денежные средства,  полученные от реализации конфискованных вещей,  явившихся орудиями совершения или предметами административных правонарушений,  обращенных в собственность субъектов Российской Федерации,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов.\n\n20. Денежные средства,  полученные от реализации конфискованных в установленном порядке орудий охоты,  рыболовства,  заготовки древесины (за исключением орудий,  изъятых в территориальном море,  на континентальном шельфе и в исключительной экономической зоне Российской Федерации)  и продукции незаконного природопользования,  подлежат зачислению по нормативу 100 процентов в бюджеты муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя по месту причинения вреда окружающей среде. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\n21. Платежи по искам о возмещении ущерба,  а также платежи,  уплачиваемые при добровольном возмещении ущерба,  причиненного государственному или муниципальному имуществу (за исключением имущества,  закрепленного за бюджетными (автономными)  учреждениями,  унитарными предприятиями) ,  подлежат зачислению в бюджеты публично-правовых образований,  в собственности которых находится указанное имущество,  по нормативу 100 процентов.\n\n22. Платежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде,  подлежат зачислению в бюджеты муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя по месту причинения вреда окружающей среде по нормативу 100 процентов,  если иное не установлено настоящим пунктом. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\nПлатежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде на особо охраняемых природных территориях федерального значения,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\nПлатежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде на особо охраняемых природных территориях регионального значения,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов.\n\nПлатежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде на особо охраняемых природных территориях местного значения,  подлежат зачислению в бюджеты муниципальных образований,  за счет которых осуществляются расходы,  связанные с охраной и использованием таких территорий,  по нормативу 100 процентов.\n\nПлатежи по искам о возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности Российской Федерации,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  если иное не установлено абзацами третьим и четвертым настоящего пункта. (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nПлатежи по искам о возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности субъекта Российской Федерации или муниципального образования,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности субъекта Российской Федерации или муниципального образования,  подлежат зачислению в бюджет соответствующего субъекта Российской Федерации или муниципального образования по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n23. Суммы штрафов,  уплачиваемых (взыскиваемых)  в соответствии с международными договорами Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов. (Дополнение пунктом - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n(Статья в редакции Федерального закона от 15.04.2019 № 62-ФЗ)","article_title":"Статья 47.2. Принятие решения о признании безнадежной к взысканию задолженности по платежам в бюджет и о ее списании (восстановлении)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2f782a82c3f26d83ad06a69c60d887916c497271bd8e2ec0a69fec6abc6497f"},{"code_id":"BK_RF","article_number":"48","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 48.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"49","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 49.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"5","version_date":"1998-07-31","article_text":"1. Закон (решение)  о бюджете вступает в силу с 1 января и действует по 31 декабря финансового года,  если иное не предусмотрено настоящим Кодексом и (или)  законом (решением)  о бюджете.\n\n2. Закон о бюджете подлежит официальному опубликованию не позднее пяти дней после его подписания в установленном порядке.\n\nРешение о бюджете подлежит официальному опубликованию не позднее 10 дней после его подписания в установленном порядке.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 5. Действие закона (решения)  о бюджете во времени","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a7fa5eb5f1f518d13b8deb519a86750e33c07a5fcfbb98b2920c0eaa62373f3"},{"code_id":"BK_RF","article_number":"50","version_date":"1998-07-31","article_text":"В федеральный бюджет зачисляются налоговые доходы от следующих федеральных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами:\n\nналога на прибыль организаций по ставке,  установленной для зачисления указанного налога в федеральный бюджет,  - по нормативу 100 процентов;\n\nналога на прибыль организаций (в части доходов иностранных организаций,  не связанных с деятельностью в Российской Федерации через постоянное представительство,  а также в части доходов,  полученных в виде дивидендов и процентов по государственным и муниципальным ценным бумагам)  - по нормативу 100 процентов;\n\nналога на прибыль организаций при выполнении соглашений о разделе продукции,  заключенных до вступления в силу Федерального закона от 30 декабря 1995 года № 225-ФЗ \"О соглашениях о разделе продукции\" (далее - Федеральный закон \"О соглашениях о разделе продукции\")  и не предусматривающих специальных налоговых ставок для зачисления указанного налога в федеральный бюджет и бюджеты субъектов Российской Федерации,  - по нормативу 25 процентов; (В редакции Федерального закона от 30.11.2016 № 409-ФЗ)\n\nналога на добавленную стоимость - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nакцизов на алкогольную продукцию с объемной долей этилового спирта свыше 9 процентов,  за исключением пива,  вин (кроме крепленого (ликерного)  вина) ,  вин наливом,  плодовой алкогольной продукции,  игристых вин,  включая российское шампанское,  а также за исключением виноградосодержащих напитков,  плодовых алкогольных напитков,  изготавливаемых без добавления ректификованного этилового спирта,  произведенного из пищевого сырья,  и (или)  без добавления спиртованных виноградного или иного плодового сусла,  и (или)  без добавления дистиллятов,  и (или)  без добавления крепленого (ликерного)  вина,  - по нормативу 16 процентов; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 244-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nакцизов на табачную продукцию - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 04.10.2014 № 283-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 30.12.2008 № 310-ФЗ)\n\nакцизов на автомобили легковые и мотоциклы - по нормативу 100 процентов;\n\nабзац; (Дополнение абзацем - Федеральный закон от 23.05.2016 № 145-ФЗ)  (Утратил силу - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nакцизов на средние дистилляты,  производимые на территории Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.12.2017 № 434-ФЗ)  (В редакции Федерального закона от 29.11.2021 № 384-ФЗ)\n\nакцизов по подакцизным товарам и продукции,  ввозимым на территорию Российской Федерации,  - по нормативу 100 процентов;\n\nналога на добычу полезных ископаемых в виде углеводородного сырья (газ горючий природный)  - по нормативу 100 процентов;\n\nналога на добычу полезных ископаемых в виде углеводородного сырья (за исключением газа горючего природного)  - по нормативу 100 процентов; (В редакции Федерального закона от 22.09.2009 № 218-ФЗ)\n\nналога на добычу полезных ископаемых (за исключением полезных ископаемых,  в отношении которых при налогообложении установлен рентный коэффициент,  отличный от 1,  полезных ископаемых в виде углеводородного сырья,  природных алмазов и общераспространенных полезных ископаемых,  угля коксующегося,  железных руд,  апатит-магнетитовых,  апатит-штаффелитовых и маложелезистых апатитовых руд,  многокомпонентной комплексной руды,  в отношении которой при налогообложении установлен коэффициент,  характеризующий стоимость ценных компонентов в руде)  - по нормативу 40 процентов; (В редакции федеральных законов от 19.12.2006 № 237-ФЗ,  от 15.10.2020 № 327-ФЗ,  от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых на континентальном шельфе Российской Федерации,  в исключительной экономической зоне Российской Федерации,  за пределами территории Российской Федерации - по нормативу 100 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  при выполнении соглашений о разделе продукции в виде углеводородного сырья (газ горючий природный)  - по нормативу 100 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  при выполнении соглашений о разделе продукции в виде углеводородного сырья (за исключением газа горючего природного)  - по нормативу 95 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  на континентальном шельфе,  в исключительной экономической зоне Российской Федерации,  за пределами территории Российской Федерации при выполнении соглашений о разделе продукции - по нормативу 100 процентов;\n\nсбора за пользование объектами водных биологических ресурсов (исключая внутренние водные объекты)  - по нормативу 20 процентов; (В редакции Федерального закона от 06.12.2007 № 333-ФЗ)\n\nсбора за пользование объектами водных биологических ресурсов (по внутренним водным объектам)  - по нормативу 20 процентов; (В редакции Федерального закона от 06.12.2007 № 333-ФЗ)\n\nводного налога - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nгосударственной пошлины (за исключением государственной пошлины за совершение юридически значимых действий,  указанных в статьях 56,  61,  611,  612,  613,  614,  615 и 616 настоящего Кодекса,  государственной пошлины,  предусмотренной абзацами тридцатым и тридцать первым настоящей статьи)  - по нормативу 100 процентов; (В редакции федеральных законов от 27.12.2009 № 374-ФЗ,  от 21.07.2014 № 249-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 07.03.2018 № 45-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 244-ФЗ)  (Утратил силу - Федеральный закон от 24.11.2014 № 374-ФЗ)\n\nгосударственной пошлины за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 50 процентов; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 249-ФЗ)\n\nгосударственной пошлины за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в электронной форме и выдачи документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 75 процентов; (Дополнение абзацем - Федеральный закон от 07.03.2018 № 45-ФЗ)\n\nакцизов на нефтяное сырье,  направленное на переработку,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nакцизов на темное судовое топливо,  производимое на территории Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nналога на дополнительный доход от добычи углеводородного сырья - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.11.2018 № 456-ФЗ)\n\nналога на доходы физических лиц в отношении доходов в виде процентов,  полученных по вкладам (остаткам на счетах)  в банках,  находящихся на территории Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nналога на доходы физических лиц в отношении доходов в виде процента (купона,  дисконта) ,  полученных по обращающимся облигациям российских организаций,  номинированным в рублях и эмитированным после 1 января 2017 года,  а также доходов в виде суммы процентов по государственным казначейским обязательствам,  облигациям и другим государственным ценным бумагам бывшего СССР,  государств - участников Союзного государства - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)  (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на добычу полезных ископаемых,  в отношении которых при налогообложении установлен рентный коэффициент,  отличный от 1,  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 327-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  уплачиваемой на основании налогового уведомления налогоплательщиками,  для которых выполнено условие,  предусмотренное абзацем восьмым пункта 6 статьи 228 Налогового кодекса Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nналога на добычу полезных ископаемых в виде угля коксующегося - по нормативу 70 процентов; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде железной руды (за исключением окисленных железистых кварцитов)  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде апатит-магнетитовых,  апатит-штаффелитовых и маложелезистых апатитовых руд - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде многокомпонентной комплексной руды,  в отношении которой при налогообложении установлен коэффициент,  характеризующий стоимость ценных компонентов в руде,  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nакциза на сталь жидкую - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nналога,  взимаемого в связи с применением специального налогового режима \"Автоматизированная упрощенная система налогообложения\",  в том числе минимального налога,  - по нормативу 46 процентов; (Дополнение абзацем - Федеральный закон от 25.02.2022 № 22-ФЗ)\n\nналога на сверхприбыль (обеспечительного платежа по налогу)  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей и составляющей не более 5 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 702 тысячи рублей,  относящейся к части налоговой базы,  превышающей 5 миллионов рублей и составляющей не более 20 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 28 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 3402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 20 миллионов рублей и составляющей не более 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 35 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 9402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать девятом и пятьдесят первом настоящей статьи) ,  - по нормативу 40 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 6 статьи 210 Налогового кодекса Российской Федерации,  превышающей 2, 4 миллиона рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом и тридцать шестом настоящей статьи) ,  а также налога на доходы физических лиц в отношении доходов физических лиц,  не являющихся налоговыми резидентами Российской Федерации,  указанных в абзаце девятом пункта 3 статьи 224 Налогового кодекса Российской Федерации,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  а также налога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  - по нормативу 13 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на природный газ,  полученный для производства аммиака,  - по нормативу 83 процента; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на фармацевтическую субстанцию спирта этилового - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на никотиновое сырье - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nакциза на бестабачную никотинсодержащую смесь для нагревания - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  уплачиваемого при выполнении условий,  предусмотренных статьями 2131,  217,  2191 и 2192 Налогового кодекса Российской Федерации,  в случаях,  если сумма всех налоговых баз налогоплательщика превышает 50 миллионов рублей,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Статья в редакции Федерального\n\nгражданина,  индивидуального предпринимателя в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве) \" - в части задолженности по платежам в бюджет,  от исполнения обязанности по уплате которой он освобожден в соответствии с указанным Федеральным законом; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n21)  (Дополнение подпунктом - Федеральный закон от 07.04.2020 № 114-ФЗ)  (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n3)  ликвидации организации - плательщика платежей в бюджет в части задолженности по платежам в бюджет,  не погашенной по причине недостаточности имущества организации и (или)  невозможности ее погашения учредителями (участниками)  указанной организации в пределах и порядке,  которые установлены законодательством Российской Федерации; (В редакции Федерального закона от 07.04.2020 № 114-ФЗ)\n\n4)  применения актов об амнистии или помилования в отношении осужденных к наказанию в виде штрафа или принятия судом решения,  в соответствии с которым администратор доходов бюджета утрачивает возможность взыскания задолженности по платежам в бюджет,  в том числе в связи с истечением установленного срока ее взыскания; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n5)  вынесения судебным приставом-исполнителем постановления об окончании исполнительного производства при возврате взыскателю исполнительного документа по основанию,  предусмотренному пунктом 3 или 4 части 1 статьи 46 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\",  если с даты образования задолженности,  размер которой не превышает размера требований к должнику,  установленного законодательством Российской Федерации о несостоятельности (банкротстве)  для возбуждения производства по делу о банкротстве,  прошло более пяти лет; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n51)  принятия судом акта о возвращении заявления о признании должника банкротом или прекращении производства по делу о банкротстве в связи с отсутствием средств,  достаточных для возмещения судебных расходов на проведение процедур,  применяемых в деле о банкротстве; (Дополнение подпунктом - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n6)  исключения юридического лица по решению регистрирующего органа из единого государственного реестра юридических лиц и наличия ранее вынесенного судебным приставом-исполнителем постановления об окончании исполнительного производства в связи с возвращением взыскателю исполнительного документа по основанию,  предусмотренному пунктом 3 или 4 части 1 статьи 46 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\",  - в части задолженности по платежам в бюджет,  не погашенной по причине недостаточности имущества организации и невозможности ее погашения учредителями (участниками)  указанной организации в случаях,  предусмотренных законодательством Российской Федерации. В случае признания решения регистрирующего органа об исключении юридического лица из единого государственного реестра юридических лиц в соответствии с Федеральным законом от 8 августа 2001 года № 129-ФЗ \"О государственной регистрации юридических лиц и индивидуальных предпринимателей\" недействительным задолженность по платежам в бюджет,  ранее признанная безнадежной к взысканию в соответствии с настоящим подпунктом,  подлежит восстановлению в бюджетном (бухгалтерском)  учете. (Дополнение подпунктом - Федеральный закон от 07.04.2020 № 114-ФЗ)\n\n2. Наряду со случаями,  предусмотренными пунктом 1 настоящей статьи,  неуплаченные административные штрафы признаются безнадежными к взысканию,  если судьей,  органом,  должностным лицом,  вынесшими постановление о назначении административного наказания,  в случаях,  предусмотренных Кодексом Российской Федерации об административных правонарушениях,  вынесено постановление о прекращении исполнения постановления о назначении административного наказания. (В редакции Федерального закона от 07.04.2020 № 114-ФЗ)\n\n3. Решение о признании безнадежной к взысканию задолженности по платежам в бюджет принимается администратором доходов бюджета на основании документов,  подтверждающих обстоятельства,  предусмотренные пунктами 1 и 2 настоящей статьи.\n\n4. Порядок принятия решений о признании безнадежной к взысканию задолженности по платежам в бюджет определяется главным администратором доходов бюджета в соответствии с общими требованиями,  установленными Правительством Российской Федерации.\n\n5. Списание (восстановление)  в бюджетном (бухгалтерском)  учете задолженности по платежам в бюджет осуществляется администратором доходов бюджета на основании решения о признании безнадежной к взысканию задолженности по платежам в бюджет.\n\nПорядок отражения операций по списанию (восстановлению)  в бюджетном (бухгалтерском)  учете задолженности по платежам в бюджет устанавливается Министерством финансов Российской Федерации.\n\n6. Положения настоящей статьи не распространяются на платежи,  установленные законодательством о налогах и сборах,  законодательством Российской Федерации об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний,  правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании,  на денежные обязательства перед публично-правовым образованием. (В редакции федеральных законов от 03.07.2016 № 346-ФЗ,  от 28.12.2017 № 434-ФЗ,  от 02.08.2019 № 278-ФЗ,  от 07.04.2020 № 114-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 406-ФЗ)","article_title":"Статья 50. Налоговые доходы федерального бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9900a66faba361e2bf3cb831dbcf0b3e12aca264243054b92ba6e9d466b5e45"},{"code_id":"BK_RF","article_number":"51","version_date":"1998-07-31","article_text":"1. Неналоговые доходы федерального бюджета формируются в соответствии со статьями 41,  42 и 46 настоящего Кодекса,  в том числе за счет:\n\nдоходов от использования имущества,  находящегося в государственной собственности Российской Федерации (за исключением имущества федеральных бюджетных и автономных учреждений,  имущества,  переданного в доверительное управление юридическим лицам,  созданным в организационно-правовой форме государственной компании,  имущества федеральных государственных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\",  а также случаев,  предусмотренных абзацами девятым,  десятым части первой и абзацами пятым,  шестым части второй статьи 57 настоящего Кодекса) ,  доходов от платных услуг,  оказываемых федеральными казенными учреждениями,  находящимися в ведении органов государственной власти Российской Федерации,  - по нормативу 100 процентов;\n\nдоходов от продажи имущества (кроме акций и иных форм участия в капитале,  государственных запасов драгоценных металлов и драгоценных камней) ,  находящегося в государственной собственности Российской Федерации,  за исключением движимого имущества федеральных бюджетных и автономных учреждений,  имущества федеральных государственных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\",  а также случаев,  предусмотренных частями восьмой - десятой статьи 62 настоящего Кодекса,  - по нормативу 100 процентов;\n\nчасти прибыли унитарных предприятий,  созданных Российской Федерацией,  остающейся после уплаты налогов и иных обязательных платежей,  - в размерах,  устанавливаемых Правительством Российской Федерации;\n\nлицензионных сборов - по нормативу 100 процентов;\n\nтаможенных пошлин и таможенных сборов - по нормативу 100 процентов;\n\nплаты за использование лесов,  расположенных на землях лесного фонда,  в части минимального размера арендной платы и минимального размера платы по договору купли-продажи лесных насаждений,  а также платы за использование лесов,  расположенных на землях иных категорий,  находящихся в федеральной собственности,  - по нормативу 100 процентов;\n\nплаты за пользование водными объектами,  находящимися в федеральной собственности,  - по нормативу 100 процентов;\n\nплаты за пользование водными биологическими ресурсами по межправительственным соглашениям - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nконсульских сборов - по нормативу 100 процентов;\n\nпатентных пошлин - по нормативу 100 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  за исключением случая,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  - по нормативу 100 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  в случае,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  - по нормативу 50 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  в случае подачи заявления о предоставлении сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  в электронной форме и выдачи указанных документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 75 процентов;\n\nсборов в счет возмещения фактических расходов,  связанных с совершением консульских действий,  - по нормативу 100 процентов;\n\nутилизационных сборов - по нормативу 100 процентов;\n\nразовых платежей за пользование недрами при наступлении событий,  предусмотренных в лицензии (за исключением участков недр,  содержащих месторождения природных алмазов,  и участков недр местного значения) ,  - по нормативу 100 процентов;\n\nрегулярных платежей за пользование недрами при пользовании недрами на территории Российской Федерации - по нормативу 40 процентов;\n\nрегулярных платежей за пользование недрами в случаях,  не указанных в абзаце девятнадцатом настоящего пункта,  - по нормативу 100 процентов; (В редакции  Федерального закона от 14.02.2024 № 13-ФЗ)\n\nплаты за заключение договора пользования рыболовным участком,  состоящим из акватории водного объекта,  находящегося в федеральной собственности,  или ее части,  - по нормативу 100 процентов; (В редакции  федеральных законов от 01.07.2021 № 251-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nплаты от продажи на аукционе права на заключение договора о закреплении доли квоты добычи (вылова)  водных биологических ресурсов и (или)  договора пользования водными биологическими ресурсами,  находящимися в федеральной собственности,  - по нормативу 100 процентов; (В редакции Федерального закона от 01.07.2021 № 251-ФЗ)\n\nсборов за участие в конкурсе (аукционе)  на право пользования участками недр (кроме участков недр местного значения)  - по нормативу 100 процентов;\n\nплаты за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  находящихся в федеральной собственности (за исключением земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации) ,  - по нормативу 100 процентов;\n\nплаты по соглашениям об установлении сервитута,  заключенным федеральными органами исполнительной власти,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  находящихся в федеральной собственности (за исключением земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации) ,  - по нормативу 100 процентов;\n\nисполнительского сбора - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 15.04.2019 № 62-ФЗ)\n\nплаты,  полученной по результатам торгов (конкурсов,  аукционов)  на право заключения договора пользования рыбоводным участком,  находящимся в федеральной собственности,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nплаты за публичный сервитут,  предусмотренной решением уполномоченного органа об установлении публичного сервитута в отношении земельных участков,  которые находятся в федеральной собственности (за исключением земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации)  и не предоставлены гражданам или юридическим лицам (за исключением органов государственной власти (государственных органов) ,  органов местного самоуправления (муниципальных органов) ,  органов управления государственными внебюджетными фондами и казенных учреждений) ,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nплаты за предоставление публично-правовой компанией в сфере государственного кадастрового учета и государственной регистрации прав сведений,  документов,  содержащихся в государственных реестрах,  за исключением случая,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 21.11.2022 № 448-ФЗ)\n\nплаты за предоставление публично-правовой компанией в сфере государственного кадастрового учета и государственной регистрации прав сведений,  документов,  содержащихся в государственных реестрах,  в случае,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  а также в случае подачи заявления о предоставлении сведений,  документов,  содержащихся в государственных реестрах,  в электронной форме и выдачи указанных документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 85 процентов; (Дополнение абзацем - Федеральный закон от 21.11.2022 № 448-ФЗ)\n\nплатежей в целях реализации мероприятий по предотвращению и ликвидации загрязнения окружающей среды в результате эксплуатации отдельного производственного объекта,  в том числе мероприятий,  реализуемых при его консервации или ликвидации,  - по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Пункт в редакции Федерального закона от 07.03.2018 № 45-ФЗ)\n\n2. В доходах федерального бюджета,  помимо перечисленных в пункте 1 настоящей статьи,  также учитываются:\n\nприбыль Центрального банка Российской Федерации,  остающаяся после уплаты налогов и иных обязательных платежей,  - по нормативам,  установленным федеральными законами; (В редакции федеральных законов от 29.05.2002 № 57-ФЗ; от 26.04.2007 № 63-ФЗ)\n\nдоходы от внешнеэкономической деятельности;\n\nабзац; (Исключен - Федеральный закон от 05.08.2000 № 116-ФЗ)\n\nсредства,  полученные организациями от реализации продуктов утилизации вооружения и военной техники после уплаты налогов,  сборов и иных обязательных платежей; (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\nсредства,  полученные от выпуска материальных ценностей из государственного запаса специального сырья и делящихся материалов после уплаты налогов,  сборов и иных обязательных платежей. (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)","article_title":"Статья 51. Неналоговые доходы федерального бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e37e88174b79ed0062f50cfe0259187991cbb716fe4e449abbbb034d97147396"},{"code_id":"BK_RF","article_number":"52","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 52.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"53","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 31.07.2020 № 263-ФЗ)","article_title":"Статья 53.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"277a000d1bab1af9bc5f7c081b8d78bbbd98a11906d6f3d1787d9722e0953934"},{"code_id":"BK_RF","article_number":"54","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 54.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"55","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 55.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"56","version_date":"1998-07-31","article_text":"1. В бюджеты субъектов Российской Федерации подлежат зачислению налоговые доходы от следующих региональных налогов:\n\nналога на имущество организаций - по нормативу 100 процентов;\n\nналога на игорный бизнес - по нормативу 100 процентов;\n\nтранспортного налога - по нормативу 100 процентов.\n\n2. В бюджеты субъектов Российской Федерации подлежат зачислению налоговые доходы от следующих федеральных налогов и сборов,  в том числе предусмотренных специальными налоговыми режимами налогов:\n\nналога на прибыль организаций по ставке,  установленной для зачисления указанного налога в бюджеты субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nналога на прибыль организаций при выполнении соглашений о разделе продукции,  заключенных до вступления в силу Федерального закона \"О соглашениях о разделе продукции\" и не предусматривающих специальных налоговых ставок для зачисления указанного налога в федеральный бюджет и бюджеты субъектов Российской Федерации,  - по нормативу 75 процентов; (В редакции Федерального закона от 30.11.2016 № 409-ФЗ)\n\nналога на доходы физических лиц (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом,  тридцать шестом,  тридцать девятом и пятьдесят седьмом статьи 50 настоящего Кодекса и абзацах пятом,  шестьдесят третьем - шестьдесят девятом настоящего пункта)  - по нормативу 85 процентов; (В редакции  федеральных законов от 30.11.2011 № 361-ФЗ,  от 23.07.2013 № 252-ФЗ,  от 15.10.2020 № 327-ФЗ,  от 01.07.2021 № 251-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nналога на доходы физических лиц,  уплачиваемого иностранными гражданами в виде фиксированного авансового платежа при осуществлении ими на территории Российской Федерации трудовой деятельности на основании патента,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 19.05.2010 № 86-ФЗ)  (В редакции федеральных законов от 03.12.2012 № 244-ФЗ; от 24.11.2014 № 374-ФЗ)\n\nакцизов на спирт этиловый из пищевого или непищевого сырья - по нормативу 100 процентов; (В редакции Федерального закона от 15.04.2019 № 62-ФЗ)\n\nакцизов на спиртосодержащую продукцию - по нормативу 100 процентов; (В редакции Федерального закона от 15.04.2019 № 62-ФЗ)\n\nакцизов на автомобильный бензин,  прямогонный бензин,  дизельное топливо,  моторные масла для дизельных и (или)  карбюраторных (инжекторных)  двигателей,  производимые на территории Российской Федерации,  - по нормативу 100 процентов; (В редакции  федеральных законов от 30.12.2008 № 310-ФЗ,  от 06.04.2011 № 68-ФЗ,  от 04.10.2014 № 283-ФЗ,  от 22.10.2014 № 311-ФЗ,  от 23.05.2016 № 145-ФЗ,  от 28.11.2018 № 456-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)  (Утратил силу - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nакцизов на алкогольную продукцию с объемной долей этилового спирта свыше 9 процентов,  за исключением пива,  вин (кроме крепленого (ликерного)  вина) ,  вин наливом,  плодовой алкогольной продукции,  игристых вин,  включая российское шампанское,  а также за исключением виноградосодержащих напитков,  плодовых алкогольных напитков,  изготавливаемых без добавления ректификованного этилового спирта,  произведенного из пищевого сырья,  и (или)  без добавления спиртованных виноградного или иного плодового сусла,  и (или)  без добавления дистиллятов,  и (или)  без добавления крепленого (ликерного)  вина,  - по нормативу 84 процента; (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nакцизов на алкогольную продукцию с объемной долей этилового спирта свыше 9 процентов,  включающую пиво,  вина (кроме крепленого (ликерного)  вина) ,  вина наливом,  плодовую алкогольную продукцию,  игристые вина,  включая российское шампанское,  а также виноградосодержащие напитки,  плодовые алкогольные напитки,  изготавливаемые без добавления ректификованного этилового спирта,  произведенного из пищевого сырья,  и (или)  без добавления спиртованных виноградного или иного плодового сусла,  и (или)  без добавления дистиллятов,  и (или)  без добавления крепленого (ликерного)  вина,  - по нормативу 100 процентов; (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 22.09.2009 № 218-ФЗ)\n\nакцизов на алкогольную продукцию с объемной долей этилового спирта до 9 процентов включительно - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nакцизов на виноградное сусло,  плодовое сусло,  плодовые сброженные материалы - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)  (В редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\nналога на добычу общераспространенных полезных ископаемых - по нормативу 100 процентов;\n\nналога на добычу полезных ископаемых (за исключением полезных ископаемых,  в отношении которых при налогообложении установлен рентный коэффициент,  отличный от 1,  полезных ископаемых в виде углеводородного сырья,  природных алмазов и общераспространенных полезных ископаемых,  угля коксующегося,  железных руд,  апатит-магнетитовых,  апатит-штаффелитовых и маложелезистых апатитовых руд,  многокомпонентной комплексной руды,  в отношении которой при налогообложении установлен коэффициент,  характеризующий стоимость ценных компонентов в руде)  - по нормативу 60 процентов; (В редакции федеральных законов от 15.10.2020 № 327-ФЗ,  от 29.11.2021 № 384-ФЗ)\n\nналога на добычу полезных ископаемых в виде природных алмазов - по нормативу 100 процентов;\n\nрегулярных платежей за добычу полезных ископаемых (роялти)  при выполнении соглашений о разделе продукции в виде углеводородного сырья (за исключением газа горючего природного)  - по нормативу 5 процентов;\n\nсбора за пользование объектами водных биологических ресурсов (исключая внутренние водные объекты)  - по нормативу 80 процентов; (В редакции Федерального закона от 06.12.2007 № 333-ФЗ)\n\nсбора за пользование объектами водных биологических ресурсов (по внутренним водным объектам)  - по нормативу 80 процентов; (Дополнение абзацем - Федеральный закон от 06.12.2007 № 333-ФЗ)\n\nсбора за пользование объектами животного мира - по нормативу 100 процентов;\n\nналога,  взимаемого в связи с применением упрощенной системы налогообложения,  в том числе минимального налога,  - по нормативу 100 процентов; (В редакции федеральных законов от 24.07.2009 № 213-ФЗ; от 30.11.2016 № 409-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 24.07.2009 № 213-ФЗ)  (Утратил силу - Федеральный закон от 30.11.2016 № 409-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\nгосударственной пошлины (подлежащей зачислению по месту государственной регистрации,  совершения юридически значимых действий или выдачи документов)  за совершение юридически значимых действий исполнительными органами субъектов Российской Федерации,  должностными лицами учреждений и иных организаций,  финансовое обеспечение деятельности которых осуществляется за счет средств бюджетов субъектов Российской Федерации,  за исключением юридически значимых действий,  совершаемых в рамках переданных полномочий в случаях,  установленных федеральными законами,  финансовое обеспечение которых осуществляется за счет субвенций из федерального бюджета,  если иное не предусмотрено настоящим пунктом,  - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 14.07.2022 № 256-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за государственную регистрацию межрегиональных,  региональных и местных общественных объединений,  отделений общественных объединений,  а также за государственную регистрацию изменений их учредительных документов - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за государственную регистрацию региональных отделений политических партий - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины\n\nвсех налоговых баз налогоплательщика превышает 50 миллионов рублей,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 56. Налоговые доходы бюджетов субъектов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3bdcbca1cddcb2adbda839bd146008d1d49e519d7d8c581379030e90e7cf206a"},{"code_id":"BK_RF","article_number":"57","version_date":"1998-07-31","article_text":"Неналоговые доходы бюджетов субъектов Российской Федерации формируются в соответствии со статьями 41,  42 и 46 настоящего Кодекса,  в том числе за счет:\n\nдоходов от использования имущества,  находящегося в государственной собственности субъектов Российской Федерации,  за исключением имущества бюджетных и автономных учреждений субъектов Российской Федерации,  а также имущества государственных унитарных предприятий субъектов Российской Федерации,  в том числе казенных,  - по нормативу 100 процентов;\n\nдоходов от продажи имущества (кроме акций и иных форм участия в капитале,  государственных запасов драгоценных металлов и драгоценных камней) ,  находящегося в государственной собственности субъектов Российской Федерации,  за исключением движимого имущества бюджетных и автономных учреждений субъектов Российской Федерации,  а также имущества государственных унитарных предприятий субъектов Российской Федерации,  в том числе казенных,  - по нормативу 100 процентов; (В редакции Федерального закона от 28.11.2018 № 457-ФЗ)\n\nдоходов от платных услуг,  оказываемых казенными учреждениями субъектов Российской Федерации;\n\nчасти прибыли унитарных предприятий,  созданных субъектами Российской Федерации,  остающейся после уплаты налогов и иных обязательных платежей в бюджет,  - в размерах,  определяемых в порядке,  установленном законами субъектов Российской Федерации;\n\nплаты за негативное воздействие на окружающую среду - по нормативу 40 процентов;\n\nплаты за использование лесов,  расположенных на землях лесного фонда,  в части,  превышающей минимальный размер арендной платы и минимальный размер платы по договору купли-продажи лесных насаждений,  платы по договору купли-продажи лесных насаждений для собственных нужд,  а также платы за использование лесов,  расположенных на землях иных категорий,  находящихся в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nабзац; (Утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nдоходов от продажи земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  передачи в аренду таких земельных участков,  продажи прав на заключение договоров аренды таких земельных участков - по нормативу не более 50 процентов;\n\nдоходов от продажи объектов недвижимого имущества одновременно с занятыми такими объектами недвижимого имущества земельными участками,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу не более 50 процентов;\n\nплаты за пользование водными объектами,  находящимися в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nразовых платежей за пользование недрами при наступлении определенных событий,  оговоренных в лицензии,  по участкам недр,  содержащих месторождения природных алмазов,  - по нормативу 100 процентов;\n\nрегулярных платежей за пользование недрами при пользовании недрами на территории Российской Федерации - по нормативу 60 процентов;\n\nразовых платежей за пользование недрами при наступлении определенных событий,  оговоренных в лицензии,  при пользовании недрами на территории Российской Федерации по участкам недр местного значения - по нормативу 100 процентов;\n\nплаты от продажи на аукционе права на заключение договора пользования водными биологическими ресурсами,  находящимися в собственности субъекта Российской Федерации,  - по нормативу 100 процентов;\n\nплаты за заключение договора пользования рыболовным участком,  состоящим из акватории водного объекта,  находящегося в собственности субъекта Российской Федерации,  или ее части,  - по нормативу 100 процентов; (В редакции  федеральных законов от 01.07.2021 № 251-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nплаты за предоставление государственными органами субъектов Российской Федерации,  казенными учреждениями субъектов Российской Федерации сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  - по нормативу 100 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  в случае,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  - по нормативу 50 процентов;\n\nплаты за предоставление федеральными государственными органами,  федеральными казенными учреждениями сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  ведение которых осуществляется данными государственными органами,  учреждениями,  в случае подачи заявления о предоставлении сведений,  документов,  содержащихся в государственных реестрах (регистрах) ,  в электронной форме и выдачи указанных документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 25 процентов;\n\nсборов за участие в конкурсе (аукционе)  на право пользования участками недр местного значения - по нормативу 100 процентов;\n\nплаты за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  находящихся в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nплаты по соглашениям об установлении сервитута,  заключенным исполнительными\n\nный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за государственную регистрацию средства массовой информации,  за внесение изменений в запись о регистрации средства массовой информации (в том числе связанных с изменением тематики или специализации) ,  продукция которого предназначена для распространения преимущественно на территории субъекта Российской Федерации,  территории муниципального образования,  - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за государственную регистрацию средства массовой информации,  за внесение изменений в запись о регистрации средства массовой информации (в том числе связанных с изменением тематики или специализации) ,  продукция которого предназначена для распространения преимущественно на всей территории Российской Федерации,  за ее пределами,  на территориях двух и более субъектов Российской Федерации,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 28.12.2017 № 434-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 27.12.2009 № 374-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за действия исполнительных органов субъектов Российской Федерации,  связанные с лицензированием образовательной деятельности,  осуществляемым в пределах переданных полномочий Российской Федерации в области образования,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 08.11.2010 № 293-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины за действия исполнительных органов субъектов Российской Федерации,  связанные с осуществляемой в пределах переданных полномочий Российской Федерации в области образования государственной аккредитацией образовательной деятельности,  - по нормативу 100 процентов; (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 08.11.2010 № 293-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 03.12.2012 № 244-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 249-ФЗ)  (Утратил силу  - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\nгосударственной пошлины (подлежащей зачислению по месту государственной регистрации,  совершения юридически значимых действий или выдачи документов)  за совершение федеральными органами исполнительной власти юридически значимых действий в случае подачи заявления и (или)  документов,  необходимых для их совершения,  в многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 50 процентов; (Дополнение абзацем - Федеральный закон от 21.07.2014 № 249-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\nгосударственной пошлины (подлежащей зачислению по месту государственной регистрации,  совершения юридически значимых действий или выдачи документов)  за совершение федеральными органами исполнительной власти юридически з